DROP TABLE IF EXISTS `sys_email_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_email_config` (
  `id` varchar(255) NOT NULL,
  `send_email` varchar(200) DEFAULT NULL COMMENT '发送人邮箱',
  `send_host` varchar(200) DEFAULT NULL COMMENT 'smtp 邮件服务器',
  `port` int(6) DEFAULT NULL COMMENT '端口',
  `password` varchar(255) DEFAULT NULL COMMENT '密码',
  `email_status` tinyint(1) DEFAULT '1' COMMENT '邮件服务状态  1  启用  0 停用',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_by_label` varchar(64) DEFAULT NULL COMMENT '创建人姓名',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='邮件服务器配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

