/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_job` (
  `job_id` varchar(32) NOT NULL COMMENT '任务ID',
  `job_name` varchar(512) DEFAULT '' COMMENT '任务名称',
  `job_group` varchar(64) DEFAULT 'DEFAULT' COMMENT '任务组名  默认的分组 DEFAULT',
  `job_group_bus_id` varchar(64) DEFAULT '' COMMENT '任务分组关联业务ID 默认的分组 DEFAULT 为空',
  `invoke_target` varchar(500) DEFAULT NULL COMMENT '调用目标字符串',
  `invoke_param` varchar(500) DEFAULT NULL COMMENT '调用目标参数',
  `cron_expression` varchar(255) DEFAULT '' COMMENT 'cron执行表达式',
  `misfire_policy` varchar(20) DEFAULT '3' COMMENT '计划执行错误策略（1立即执行 2执行一次 3放弃执行）',
  `start_time` datetime DEFAULT NULL COMMENT '任务开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '任务结束时间',
  `next_fire_time` datetime DEFAULT NULL COMMENT '定时任务下一次调度时间',
  `concurrent` varchar(1) DEFAULT '1' COMMENT '是否并发执行（0允许 1禁止）',
  `status` varchar(1) DEFAULT '0' COMMENT '状态（0正常 1暂停）',
  `remark` varchar(500) DEFAULT '' COMMENT '备注信息',
  `del_flag` varchar(2) DEFAULT '0' COMMENT '删除标记(0正常 1删除)',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`job_id`),
  KEY `sys_job_name_IDX` (`job_name`) USING BTREE,
  KEY `sys_job_group_IDX` (`job_group`) USING BTREE,
  KEY `sys_job_group_bus_id_IDX` (`job_group_bus_id`) USING BTREE,
  KEY `sys_job_status_IDX` (`status`) USING BTREE,
  KEY `sys_job_del_flag_IDX` (`del_flag`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='定时任务调度表';
/*!40101 SET character_set_client = @saved_cs_client */;

