--
-- Table structure for table `sys_service_node_config`
--

DROP TABLE IF EXISTS `sys_service_node_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_service_node_config` (
  `id` varchar(32) NOT NULL,
  `node_name` varchar(100) DEFAULT NULL COMMENT '本节点名称',
  `affiliation_dept_name` varchar(100) DEFAULT NULL COMMENT '本节点归属组织',
  `affiliation_dept_node_id` varchar(24) DEFAULT NULL COMMENT '本节点归属组织id',
  `area` tinyint(1) DEFAULT NULL COMMENT '所属网域',
  `parent_host` varchar(200) DEFAULT NULL COMMENT '上级节点地址',
  `parent_port` varchar(10) DEFAULT NULL COMMENT '上级节点端口',
  `user_name` varchar(100) DEFAULT NULL COMMENT '注册账号',
  `password` text COMMENT '注册密码',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_by_label` varchar(64) DEFAULT NULL COMMENT '创建人账号',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `del_flag` tinyint(1) DEFAULT '0' COMMENT '删除标记 0 未删除  1已删除',
  `connect_status` tinyint(1) DEFAULT NULL COMMENT '连接状态 1 已连接 2断线',
  `connect_time` datetime DEFAULT NULL COMMENT '最近连接时间',
  `dept_name_and_id` varchar(200) DEFAULT NULL COMMENT '归属组织名称以及id',
  `type` tinyint(1) DEFAULT NULL COMMENT '1 保存 2 注册',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='服务节点配置';
/*!40101 SET character_set_client = @saved_cs_client */;

