  `equipment_type` varchar(50) DEFAULT NULL COMMENT '设备型号',
  `is_encore` char(1) DEFAULT NULL COMMENT '是否安可 0否  1是',
  `storage_system` varchar(20) DEFAULT NULL COMMENT '存储系统（套数）',
  `capacity` varchar(20) DEFAULT NULL COMMENT '容量（T）',
