  `personal_info_type` varchar(500) DEFAULT NULL COMMENT '个人信息类型',
  `personal_info_order` varchar(100) DEFAULT NULL COMMENT '个人信息量级',
  `unique_code` varchar(128) DEFAULT NULL COMMENT '外部系统唯一标识',
  `application_type` varchar(50) DEFAULT NULL COMMENT '应用类别 选项取字典:asset_application_type',
  `device_type` varchar(20) DEFAULT NULL COMMENT '设备类型(软件、硬件、其他)',
