  `purchase_time` datetime DEFAULT NULL COMMENT '采购时间(yyyyMMdd)',
  `real_source` varchar(20) DEFAULT NULL COMMENT '外部供应商真实来源',
  `use_bod` text COMMENT '使用人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `internal_ip` (`internal_ip`,`del_flag`),
  KEY `tb_asset_area_IDX` (`area`,`sub_area`) USING BTREE,
  KEY `tb_asset_area_ip_IDX` (`area`,`internal_ip`) USING BTREE,
  KEY `idx_ass_internet_ip` (`internet_ip`),
  KEY `idx_ass_del_flag` (`del_flag`),
  KEY `idx_ass_update_time` (`update_time`),
  KEY `idx_dept_path` (`dept_path`),
  KEY `idx_area_path` (`area_path`),
  KEY `idx_asset_type_path` (`asset_type_path`),
  KEY `idx_internal_ip` (`internal_ip`),
  KEY `idx_unique_code` (`unique_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='资产信息表';
