DROP TABLE IF EXISTS `tb_notice_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tb_notice_task` (
  `id` varchar(32) NOT NULL,
  `task_id` varchar(32) DEFAULT NULL COMMENT '任务ID',
  `task_title` varchar(255) DEFAULT NULL COMMENT '任务标题',
  `task_type` varchar(255) DEFAULT NULL COMMENT '任务类型 1：普通 2：阶段计划类 3：文件签订类',
  `rer_project` varchar(64) DEFAULT NULL COMMENT '关联项目',
  `task_end_time` datetime DEFAULT NULL COMMENT '截止时间',
  `task_level` varchar(1) DEFAULT NULL COMMENT '优先级，0低，1中，2高，3紧急',
  `task_status` int(11) DEFAULT '0' COMMENT '任务状态：0待下发，1已下发',
  `task_detail` longtext COMMENT '任务内容',
  `file_json` text COMMENT '附件',
  `remark` text COMMENT '补充备注',
  `publish_time` datetime DEFAULT NULL COMMENT '下发时间',
  `publish_user` varchar(32) DEFAULT NULL COMMENT '下发用户',
  `publish_username` varchar(255) DEFAULT NULL COMMENT '下发用户名称',
  `push_mail` varchar(1) DEFAULT NULL COMMENT '邮件发送开关 0：停用 1：启用',
  `push_oa` varchar(1) DEFAULT NULL COMMENT 'OA发送开关 0：停用 1：启用',
  `secrecy_protocol` varchar(1) DEFAULT '0' COMMENT '是否保密协议 0：否 1：是,默认为0',
  `sign_content` text COMMENT '签字内容',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_by_label` varchar(255) DEFAULT NULL COMMENT '创建姓名',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` varchar(1) DEFAULT NULL COMMENT '0-有效，1-已删除',
  `task_users` text COMMENT '暂存执行人ID信息',
  `frequency` char(1) DEFAULT '1' COMMENT '通知频率 1：即时通知 2：每月通知 3：每周通知 4：每天通知',
  `frequency_concrete` varchar(128) DEFAULT NULL COMMENT '巡检频率具体是哪一天或者周几',
  `notice_time` time DEFAULT NULL COMMENT '通知时间',
  `exec_user_type` char(1) DEFAULT '1' COMMENT '执行人类型 1：按用户 2：按组织',
  `affiliation_dept_node_id` text COMMENT '组织id',
  `json_data` longtext COMMENT '任务模板json数据',
  `affiliation_dept_name` text COMMENT '组织全称，用英文逗号分隔',
  `task_start_time` datetime DEFAULT NULL COMMENT '任务开始时间',
  `is_seal` char(1) DEFAULT NULL COMMENT '是否盖章 0：否 1：是',
  `file_title` varchar(128) DEFAULT NULL COMMENT '文件标题',
  `add_user_type` char(1) DEFAULT NULL COMMENT '添加执行人类型 0：选择角色 1：选择用户',
  `json_dept_user` text COMMENT '部门人员对应json数组',
  `progress_flag` char(1) DEFAULT '0' COMMENT '进度计划标识 0：年度计划 1：月度计划',
  PRIMARY KEY (`id`),
  KEY `task_title` (`task_title`(32)) USING BTREE,
  KEY `task_type` (`task_type`(32)),
  KEY `task_id` (`task_id`),
  KEY `idx_exec_user_type` (`exec_user_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='通知任务';
/*!40101 SET character_set_client = @saved_cs_client */;

