CREATE TABLE `tb_process_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `process_key` varchar(40) DEFAULT NULL COMMENT '流程标识',
  `process_name` varchar(32) DEFAULT NULL COMMENT '流程名称',
  `process_icon` varchar(10) DEFAULT NULL COMMENT '流程icon',
  `process_desc` varchar(100) DEFAULT NULL COMMENT '流程描述',
  `process_type` varchar(32) DEFAULT NULL COMMENT '流程分组类型',
  `process_type_name` varchar(32) DEFAULT NULL COMMENT '流程分组类型名称',
  `process_owner` varchar(40) DEFAULT NULL COMMENT '流程归属',
  `starter_person_type` varchar(32) DEFAULT NULL COMMENT '发起人节点人员类型（role-角色；people-具体人;peopleGroup-用户组）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0 未发布，1已发布）',
  `is_show` char(1) DEFAULT NULL COMMENT '是否列表显示（0 显示，1 不显示）',
  `is_enable` char(1) DEFAULT NULL COMMENT '是否启用（0 启用，1 禁用）',
  `process_data` text COMMENT '节点数据',
  `create_by` varchar(64) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `enable_time` datetime DEFAULT NULL COMMENT '启用时间',
  `publish_time` datetime DEFAULT NULL COMMENT '流程发布时间',
  `update_by` varchar(64) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `starter_person_data` varchar(512) NOT NULL DEFAULT '',
  `starter_person_data_label` varchar(512) NOT NULL DEFAULT '',
  `organization` varchar(30) DEFAULT NULL COMMENT '所属组织',
  `organization_id` bigint(20) DEFAULT NULL COMMENT '所属组织id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='流程信息\r\n';
