--
-- Table structure for table `tb_top_config_rel`
--

DROP TABLE IF EXISTS `tb_top_config_rel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tb_top_config_rel` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `top_id` bigint(20) DEFAULT NULL COMMENT 'top主键id',
  `rel_id` varchar(64) DEFAULT NULL COMMENT '关联id',
  `rel_type` char(1) DEFAULT NULL COMMENT '关联类型 0：资产 1：网段 2：应用系统',
  `del_flag` varchar(1) DEFAULT '0' COMMENT '删除标识，0未删除，1已删除',
  PRIMARY KEY (`id`),
  KEY `idx_top_id` (`top_id`) USING BTREE,
  KEY `idx_rel_id` (`rel_id`) USING BTREE,
  KEY `idx_rel_type` (`rel_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='top配置关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

