--
-- Table structure for table `tb_visual_chart`
--

DROP TABLE IF EXISTS `tb_visual_chart`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tb_visual_chart` (
  `id` varchar(64) NOT NULL COMMENT '主键ID',
  `code` varchar(80) NOT NULL COMMENT '报表编号',
  `name` varchar(100) DEFAULT NULL COMMENT '标题',
  `type` varchar(64) DEFAULT NULL COMMENT '类型',
  `data_type` varchar(64) DEFAULT NULL COMMENT '数据类型（dsl、sql、static）',
  `source` varchar(512) DEFAULT NULL COMMENT '数据来源',
  `json_data` text COMMENT '数据',
  `data_property` text COMMENT '数据参数',
  `json_param` varchar(500) DEFAULT NULL COMMENT '入参',
  `json_property` text COMMENT '报表属性',
  `theme` varchar(64) DEFAULT NULL COMMENT '主题颜色',
  `number` varchar(11) DEFAULT NULL COMMENT '返回数据量',
  `min_width` varchar(10) DEFAULT NULL COMMENT '报表最低宽度',
  `min_height` varchar(10) DEFAULT NULL COMMENT '报表最低高度',
  `default_width` varchar(10) DEFAULT NULL COMMENT '报表默认宽度',
  `default_height` varchar(10) DEFAULT NULL COMMENT '报表默认高度',
  `background` varchar(200) DEFAULT NULL COMMENT '背景',
  `cache` int(11) DEFAULT '0' COMMENT '0 不缓存  其他数字代表缓存多少分钟',
  `es_index` varchar(218) DEFAULT NULL COMMENT 'DSL语句的es索引',
  `json_tab` text COMMENT '表头 json格式',
  `memo` varchar(500) DEFAULT NULL COMMENT '描述',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_by_label` varchar(64) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '修改者',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `group_id` varchar(50) DEFAULT NULL COMMENT '分组ID',
  `status` char(1) DEFAULT NULL COMMENT '状态 0：未发布 1：已发布',
  `group_path` text COMMENT '分组路径',
  `relation_type` varchar(1) DEFAULT NULL,
  `relation_content` text COMMENT '报表关联方式内容',
  `relation_open` tinyint(1) DEFAULT NULL COMMENT ' 1:  新开窗口   2：当前替换  3：当前并存',
  `relation_params` varchar(1000) DEFAULT NULL COMMENT '关联配置的参数',
  `relation_way` tinyint(1) DEFAULT NULL COMMENT ' 1.下钻   2.跳转',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='可视化管理';
