INSERT INTO `tb_visual_chart` VALUES ('152','S-000001','11','count','sql','','SELECT COUNT(1) AS COUNT FROM tb_vuln_data',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"漏洞总数/个\"}','blue','','3','3','3','3','/profile/upload/2021/09/04/202109041608516980001.png',0,'',NULL,'','huganpu','huganpu','2021-09-04 16:08:57','super','2023-11-17 15:20:51','100','1','100',NULL,'',0,NULL,0),('153','S-000002','[智慧安全协同平台｜脆弱性态势] 未修复漏洞数量','count','sql','','SELECT COUNT(1) AS COUNT FROM tb_vuln_data WHERE STATUS = 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"未修复漏洞数量/个\"}','blue',NULL,'3','3','3','3','/profile/upload/2021/09/04/202109041634273850002.png',0,'',NULL,NULL,'super','管理员','2021-09-04 16:34:36','super','2022-01-14 14:08:33','100','1','100',NULL,NULL,NULL,NULL,NULL),('154','S-000003','[智慧安全协同平台｜脆弱性态势] 已修复漏洞数量','count','sql','','SELECT COUNT(1) AS COUNT FROM tb_vuln_data WHERE STATUS = 1',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"已修复漏洞数量/个\"}','blue',NULL,'3','3','3','3','/profile/upload/2021/09/04/202109041652131120000.png',0,'',NULL,NULL,'super','管理员','2021-09-04 16:52:16','super','2022-01-14 14:08:37','100','0','100',NULL,NULL,NULL,NULL,NULL),('155','S-000004','[智慧安全协同平台｜脆弱性态势] 误报漏洞数量','count','sql','','SELECT COUNT(1) AS COUNT FROM tb_vuln_data WHERE STATUS = 2',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"误报漏洞数量/个\"}','blue',NULL,'3','3','3','3','/profile/upload/2021/09/04/202109041700199020001.png',0,'',NULL,NULL,'super','管理员','2021-09-04 17:00:23','super','2022-01-14 14:08:29','100','0','100',NULL,NULL,NULL,NULL,NULL),('156','S-000005','[智慧安全协同平台｜脆弱性态势] 新发现漏洞趋势','area','sql','','SELECT COUNT(1) AS COUNT,DATE_FORMAT(recently_time, \'%Y-%m-%d\') AS NAME FROM tb_vuln_data WHERE DATE_FORMAT(recently_time, \'%Y-%m-%d\') between dateStart and dateEnd GROUP BY DATE_FORMAT(recently_time, \'%Y-%m-%d\') ',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"gridBottom\":\"8%\",\"areaColor\":\"#B3DEFF\",\"legendData\":\"新发现漏洞数量\",\"smooth\":true,\"xaxisLabelRotate\":true,\"xaxisLabelRotate\":30,\"dataFillUp\":{\"dataType\":\"date\",\"interval\":\"day\",\"dateFormat\":\"yyyy-MM-dd\",\"dataRange\":[\"dateStart\",\"dateEnd\"],\"fillData\":0}}','blue',NULL,'6','5','6','5',NULL,0,'',NULL,NULL,'super','管理员','2021-09-04 17:02:23','super','2022-01-14 14:08:24','100','0','100',NULL,NULL,NULL,NULL,NULL),('157','S-000006','[智慧安全协同平台｜脆弱性态势] 待修复漏洞数量','bar','sql','','SELECT COUNT(1) AS COUNT, d.dept_name  AS NAME FROM tb_vuln_data v LEFT JOIN sys_dept d ON v.organ_id = d.dept_id  WHERE v.status = 0 and d. dept_name != \"\" GROUP BY d.dept_name ORDER BY COUNT DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":\"待修复漏洞数量\"}','blue','10','6','5','6','5',NULL,0,'',NULL,NULL,'super','管理员','2021-09-04 17:19:57','super','2022-01-14 14:08:19','100','0','100',NULL,NULL,NULL,NULL,NULL),('158','S-000007','[智慧安全协同平台｜脆弱性态势] 高危漏洞分布Top10（按组织）','annular','sql','','SELECT COUNT(1) AS COUNT, d.dept_name  AS NAME FROM tb_vuln_data v LEFT JOIN sys_dept d ON v.organ_id = d.dept_id  WHERE v.LEVEL > 1 and d.dept_name != \"\" GROUP BY d.dept_name ORDER BY COUNT DESC LIMIT 10',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"showNum\":true}','blue','10','4','3','4','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-04 17:29:30','super','2022-01-14 14:08:15','100','0','100',NULL,NULL,NULL,NULL,NULL),('159','S-000008','[智慧安全协同平台｜脆弱性态势] 高危漏洞分布Top10（按实例）','annular','sql','','SELECT COUNT(1) AS COUNT, v.instance AS NAME FROM tb_vuln_data v  WHERE v.instance != \"\" AND v.LEVEL > 1 GROUP BY v.instance ORDER BY COUNT DESC LIMIT 10',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"showNum\":true}','blue','10','4','3','4','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-04 17:42:08','super','2022-01-14 14:08:08','100','0','100',NULL,NULL,NULL,NULL,NULL),('160','S-000009','[智慧安全协同平台｜脆弱性态势] 高危漏洞分布Top10（按IP）','annular','sql','','SELECT COUNT(1) AS COUNT, v.ip AS NAME FROM tb_vuln_data v  WHERE v.ip != \"\" AND v.LEVEL > 1 GROUP BY v.ip ORDER BY COUNT DESC LIMIT 10',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"showNum\":true}','blue','10','4','3','4','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-04 18:57:12','super','2022-01-14 14:08:04','100','0','100',NULL,NULL,NULL,NULL,NULL),('161','S-000010','[智慧安全协同平台｜脆弱性态势] 漏洞排行榜Top10','table','sql','',' SELECT  v1.name,  v1.count, IFNULL(v2.count2, 0) count2 FROM (SELECT COUNT(1) AS COUNT, NAME FROM tb_vuln_data GROUP BY NAME ORDER BY COUNT DESC ) v1 LEFT JOIN ( SELECT COUNT(1) AS count2, NAME FROM tb_vuln_data WHERE LEVEL > 1 GROUP BY NAME  ) v2 ON v1.name = v2.name  ORDER BY v1.count DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"漏洞名称\",\"field\":\"name\"},{\"name\":\"漏洞总数\",\"field\":\"count\"},{\"name\":\"危急/高危数量\",\"field\":\"count2\"}]}','blue','10','4','3','4','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-06 13:54:03','super','2022-01-14 14:07:59','100','0','100',NULL,NULL,NULL,NULL,NULL),('162','S-000011','[智慧安全协同平台｜脆弱性态势] 组织漏洞修复率','bar','sql','','SELECT NAME, IF(countVuln = 0, 0, CONVERT(countVuln/sumVuln * 100,DECIMAL(10,2))) COUNT FROM (\nSELECT d.dept_name NAME, IFNULL(t.count, 0) countVuln, IFNULL(a.count, 0) sumVuln FROM sys_dept d \nLEFT JOIN ( SELECT COUNT(1) COUNT, organ_id FROM tb_vuln_data WHERE STATUS = 1 AND organ_id  != \"\" GROUP BY organ_id ) t \nON t.organ_id = d.dept_id\nLEFT JOIN ( SELECT COUNT(1) COUNT, organ_id FROM tb_vuln_data WHERE organ_id  != \"\" GROUP BY organ_id ) a\nON a.organ_id = d.dept_id\nWHERE d.parent_id = 100\n) t\nORDER BY COUNT DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":\"漏洞修复率\",\"yAxisUnit\":\"%\"}','blue','1','4','3','4','3',NULL,0,'',NULL,'报表描述','super','管理员','2021-09-06 14:10:22','super','2022-06-15 16:38:03','100','0','100',NULL,NULL,NULL,NULL,NULL),('163','S-000012','[智慧安全协同平台｜脆弱性态势] 漏洞类型分布','annular','sql','','SELECT COUNT(1) AS COUNT, v.vuln_type  AS NAME FROM tb_vuln_data v WHERE v.vuln_type != \"\" GROUP BY v.vuln_type ORDER BY COUNT DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"showNum\":true}','blue',NULL,'4','3','4','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-07 15:38:24','super','2022-01-14 14:07:47','100','0','100',NULL,NULL,NULL,NULL,NULL),('164','S-000013','[智慧安全协同平台｜脆弱性态势] 漏洞等级分布','annular','sql','','SELECT COUNT(1) AS COUNT, d.dict_label  AS NAME FROM tb_vuln_data v LEFT JOIN ( SELECT dict_label, dict_value FROM sys_dict_data WHERE dict_type = \'vul_level\' ) d ON v.level = d.dict_value  GROUP BY d.dict_label ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'38%\', \'50%\'],\"legendright\":\"1%\",\"legendDataColor\":{\"危急\":\"#FFA39E\",\"高危\":\"#FFCA8F\",\"中危\":\"#C5C0FF\",\"低危\":\"#91C3FF\"},\"showNum\":true,\"dataFillUp\":{\"dataType\":\"list\",\"dataRange\":[\"危急\",\"高危\",\"中危\",\"低危\"],\"fillData\":0}}','colorgroup2',NULL,'2','2','4','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-07 15:47:43','super','2022-01-14 14:07:35','100','0','100',NULL,NULL,NULL,NULL,NULL),('187','S-000020','钓鱼邮件-全集团-邮件发送数和送达数','text-progress','sql','','SELECT IFNULL( total , 0 ) AS 邮件发送数 , IFNULL( num_of_send , 0 ) AS 送达数 , \r\nIFNULL( num_of_send/total*100, 0 ) AS 送达率  \r\nFROM task_infos WHERE task_id = \"${taskId<202111151>}\" ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"邮件发送数\",\"num\":1},{\"key\":\"送达数\",\"num\":2},{\"key\":\"送达率\",\"num\":3}]}','singleGreen',NULL,'3','3','3','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-27 16:52:58','super','2021-09-28 14:04:32','100','1','100',NULL,NULL,NULL,NULL,NULL),('188','S-000021','钓鱼邮件-全集团-中招人数','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS \'中招数\', \r\nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 )  AS \'中招率\' \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"中招数\",\"num\":1},{\"key\":\"中招率\",\"num\":2}]}','singleRed',NULL,'3','3','3','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-27 17:54:30','super','2021-09-28 14:05:31','100','1','100',NULL,NULL,NULL,NULL,NULL),('189','S-000022','钓鱼邮件-全集团-打开附件人数','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 打开附件人数 , \r\nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) AS 打开率 \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 2 ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"打开附件人数\",\"num\":1},{\"key\":\"打开率\",\"num\":2}]}','singleYellow',NULL,'3','3','3','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-27 18:17:54','super','2021-09-28 14:06:03','100','1','100',NULL,NULL,NULL,NULL,NULL),('190','S-000023','钓鱼邮件-全集团-点击链接人数','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 点击链接人数 , \r\nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) AS 点击率 \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 1 ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"点击链接人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue',NULL,'3','3','3','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-27 18:19:29','super','2021-09-28 14:06:20','100','1','100',NULL,NULL,NULL,NULL,NULL),('191','S-000024','钓鱼邮件-全集团-各单位中招情况','bar','sql','','(SELECT t.bu_name AS NAME , IFNULL(capCount, 0)/t.num_of_send * 100 AS COUNT, \'中招率\' AS CHILD\r\nFROM task_info t\r\n    LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\"  GROUP BY e.depend1 ) a ON a.task_id = t.task_id AND t.bu_name = a.depend1\r\n	  WHERE t.task_id = \"${taskId<202111151>}\" AND t.bu_parent = \'\'\r\nORDER BY COUNT DESC\r\n)UNION(\r\nSELECT t.bu_name AS NAME , IFNULL(capCount, 0 ) AS COUNT, \'中招人数\' AS CHILD\r\nFROM task_info t\r\n    LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\"  GROUP BY e.depend1 ) a ON a.task_id = t.task_id AND t.bu_name = a.depend1\r\n	  WHERE t.task_id = \"${taskId<202111151>}\" AND t.bu_parent = \'\'\r\nORDER BY COUNT DESC)',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{legendData:[\"中招人数\",\"中招率\"],\"yTwoAxisUnit\":\"%\",\"yTwoAxisLegend\":\"中招率\",\"labelPosition\":\"top\",\"labelFontSize\":11,\"legendDataColor\":{\"中招人数\":\"#71a3f3\",\"中招率\":\"#ffc836\"},\"barGap\":\"100%\",\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2}],\"dataOrder\":{\"field\":\"中招率\",\"sort\":\"desc\"}}','blueYellow',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-09-28 10:19:35','super','2021-09-30 14:35:31','100','1','100',NULL,NULL,NULL,NULL,NULL),('192','S-000025','钓鱼邮件-全集团-中招高峰时间分布','area','sql','','( SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'点击链接人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 1 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\r\nUNION\r\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'点击附件人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 2 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\r\nORDER BY NAME ASC\r\n',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'blueYellow',NULL,'3','3','3','3',NULL,0,'',NULL,NULL,'super','管理员','2021-09-28 10:55:59','super','2021-09-30 18:54:34','100','1','100',NULL,NULL,NULL,NULL,NULL),('193','S-000026','钓鱼邮件-全集团-中招率趋势','line','sql','','SELECT cap_rate AS COUNT, cap_name AS NAME FROM (\r\nSELECT * FROM task_cap  WHERE cap_start <= ( SELECT cap_start FROM task_cap WHERE task_id =  \"${taskId<2021102201>}\" AND bu_name = \"${buName<华润集团（全集团）>}\" )   \r\nAND bu_name = \"${buName<华润集团（全集团）>}\" AND task_type = ( SELECT task_type FROM task_cap WHERE task_id =  \"${taskId<2021102201>}\" AND bu_name = \"${buName<华润集团（全集团）>}\")\r\nORDER BY cap_start DESC LIMIT 0,5 ) AS t ORDER BY t.cap_start ASC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":\"中招率\",\"yAxisUnit\":\"%\",\"xaxisLabelRotate\":30}','singleBlue',NULL,'4','4','6','5',NULL,0,'',NULL,NULL,'super','管理员','2021-09-28 16:10:08','super','2022-01-12 16:25:28','100','1','100',NULL,NULL,NULL,NULL,NULL),('194','S-000027','钓鱼邮件-全集团-各单位中招数据','table','sql','','( SELECT @rownum:=@rownum+1 AS \'排名\' , t.* FROM ( SELECT t.bu_name AS \'单位\' , IFNULL( t.total, 0 ) AS \'邮件发送数\', \r\nIFNULL( t.num_of_send, 0 ) AS \'邮件送达数\', IFNULL(capCount, 0 ) AS \'中招人数\',\r\nIFNULL(capCount, 0)/t.num_of_send * 100 AS \'中招率\', \r\nIFNULL(openCount, 0) AS \'打开附件人数\', \r\nIFNULL(openCount, 0)/t.num_of_send * 100 AS \'附件打开率\',  \r\nIFNULL(linkCount, 0) AS \'点击链接人数\', \r\nIFNULL(linkCount, 0)/t.num_of_send * 100 AS \'链接点击率\'\r\nFROM task_info t\r\n    LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\"  GROUP BY e.depend1 ) a ON a.task_id = t.task_id AND t.bu_name = a.depend1\r\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS openCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 2 GROUP BY e.depend1 ) b\r\n	    ON a.depend1 = b.depend1\r\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS linkCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 1 GROUP BY e.depend1 ) c\r\n	    ON a.depend1 = c.depend1\r\n	  WHERE t.task_id = \"${taskId<202111151>}\" AND t.bu_parent = \'\'\r\nORDER BY 中招率 DESC ) t, (SELECT @rownum:=0) r ) \r\nUNION (\r\nSELECT \'总计\' AS \'排名\',  \'\' AS \'单位\',\r\n(SELECT IFNULL( total , 0 )  FROM task_infos WHERE task_id = \"${taskId<202111151>}\")  AS \'邮件发送数\',\r\n(SELECT IFNULL( num_of_send , 0 )  FROM task_infos WHERE task_id = \"${taskId<202111151>}\")  AS \'邮件送达数\',\r\n(SELECT COUNT( DISTINCT(e.email) ) \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\") AS \'中招人数\', \r\n( SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\") AS \'中招率\', \r\n(SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 2  ) AS \'打开附件人数\', \r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 2 ) AS \'附件打开率\' ,\r\n( SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 1 ) AS \'点击链接人数\',\r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\r\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 1) AS \'链接点击率\'\r\n\r\n) ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"排名\",\"field\":\"排名\"},{\"name\":\"单位\",\"field\":\"单位\"},{\"name\":\"邮件发送数\",\"field\":\"邮件发送数\"},{\"name\":\"邮件送达数\",\"field\":\"邮件送达数\"},{\"name\":\"中招人数\",\"field\":\"中招人数\"},{\"name\":\"中招率\",\"field\":\"中招率\"},{\"name\":\"打开附件人数\",\"field\":\"打开附件人数\"},{\"name\":\"附件打开率\",\"field\":\"附件打开率\"},{\"name\":\"点击链接人数\",\"field\":\"点击链接人数\"},{\"name\":\"链接点击率\",\"field\":\"链接点击率\"}],\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"附件打开率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"链接点击率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"}]}','blue',NULL,'4','4','4','4',NULL,0,'',NULL,NULL,'super','管理员','2021-09-28 18:23:16','super','2021-09-30 17:59:31','100','1','100',NULL,NULL,NULL,NULL,NULL),('1ddc7588aca347c8bb66401a62078550','S-000055','[智慧安全威胁与态势分析平台｜安全监控｜监控总览] 日志风险等级分布（近24小时）','annular','dsl','','{\"aggs\":{\"name\":{\"terms\":{\"field\":\"log_level.keyword\",\"order\":{\"_count\":\"desc\"},\"size\":5}}},\"size\":0,\"stored_fields\":[\"*\"],\"script_fields\":{},\"docvalue_fields\":[{\"field\":\"SparkTime\",\"format\":\"date_time\"},{\"field\":\"alert_time\",\"format\":\"date_time\"},{\"field\":\"log_start_time\",\"format\":\"date_time\"}],\"_source\":{\"excludes\":[]},\"query\":{\"bool\":{\"must\":[],\"filter\":[{\"match_all\":{}},{\"bool\":{\"should\":[{\"match_phrase\":{\"log_level.keyword\":\"低风险\"}},{\"match_phrase\":{\"log_level.keyword\":\"中风险\"}},{\"match_phrase\":{\"log_level.keyword\":\"高风险\"}},{\"match_phrase\":{\"log_level.keyword\":\"信息\"}}],\"minimum_should_match\":1}},{\"range\":{\"SparkTime\":{\"gte\":dateStart,\"lte\":dateEnd,\"format\":\"strict_date_optional_time\"}}}],\"should\":[],\"must_not\":[]}}}',NULL,