me like \'%ZooKeeper%\' then \'ZooKeeper\'\nwhen soft_name like \'%jetty%\' then \'Jetty\'\nwhen soft_name like \'%jboss%\' then \'Jboss\'\nwhen soft_name like \'%weblogic%\' then \'Weblogic\'\nwhen soft_name like \'%kafka%\' then \'Kafka\'\nwhen soft_name like \'%activemq%\' then \'ActiveMQ\'\nelse soft_name end as name,\ncount(*) as count from tb_asset_software where second_cat_tag=\'中间件\' and DATE_SUB(CURDATE(), INTERVAL 2 DAY)&lt;=last_check_time group by name order by count(*) desc limit 20',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5}','colorgroup1','20','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-03 15:13:04','super','2022-11-03 15:13:04','100','0','100',NULL,NULL,NULL,NULL,NULL),('202211031513037660036','S-000337','资产全景_资产开放端口TOP20_副本','annular','sql','','SELECT COUNT(1) AS COUNT, \nport AS NAME FROM tb_asset_port\nGROUP BY port ORDER BY COUNT DESC LIMIT 20',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5}','colorgroup1','20','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-03 15:13:04','super','2022-11-03 15:13:04','100','0','100',NULL,NULL,NULL,NULL,NULL),('202211031513037770037','S-000336','资产全景_各单位资产分布Top20_副本','bar','sql','','SELECT COUNT(1) COUNT, affiliation_dept_name AS NAME, \'IP资产总数\' AS CHILD \nFROM tb_asset \nWHERE affiliation_dept_name != \"\" AND  del_flag = 0 AND affiliation_dept_name is not null \nGROUP BY affiliation_dept_name \nUNION (\nSELECT COUNT(1) COUNT, affiliation_dept_name AS NAME, \'中高风险资产数\' AS CHILD \nFROM tb_asset\nWHERE affiliation_dept_name != \"\" AND  del_flag = 0 AND affiliation_dept_name is not null AND safety_score &lt; \'70\'\nGROUP BY affiliation_dept_name \n)   ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"