deptId<\'\'>}\'\n      UNION\n      SELECT\n        ta.`id`\n      FROM\n        tb_asset ta\n        INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n      WHERE sd.`del_flag` = \'0\'\n        AND ta.`del_flag` = \'0\'\n        AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n        $[AND ta.`affiliation_dept_node_id` IN (${authDeptIdStr})]$\n    ) t3 ON t2.`id` = t3.`id`\n  GROUP BY t1.`port`\n  ORDER BY ipAssetNumber DESC\n  LIMIT 10) tt\n  LEFT JOIN sys_dict_data sdd ON tt.`port` = sdd.`dict_value` AND sdd.`dict_type` = \'asset_ip_highrisk_port\' AND sdd.`status` = \'0\'\nORDER BY ipAssetNumber DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 14:54:05','super','2023-08-12 09:47:47','100','1','100',NULL,'',0,NULL,0),('20221109152135110006','S-000360','资产全景-资产常用组件TOP20','annular','sql','','SELECT\n    t1.`soft_name` AS softName,\n    COUNT(DISTINCT t1.`ip`) AS ipAssetNumber\n  FROM\n    tb_asset_software t1\n    INNER JOIN\n      (SELECT\n        ta.`internal_ip`\n      FROM\n        tb_asset ta\n      WHERE ta.`del_flag` = \'0\'\n        AND ta.`dept_path` LIKE \'%,99%\' \n        AND 100 = \'${deptId<\'\'>}\'\n      UNION\n      SELECT\n        ta.`internal_ip`\n      FROM\n        tb_asset ta\n        INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n      WHERE sd.`del_flag` = \'0\'\n        AND ta.`del_flag` = \'0\'\n        AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n        $[AND ta.`affiliation_dept_node_id` IN (${authDeptIdStr})]$\n    ) t2 ON t1.`ip` = t2.`internal_ip`\nGROUP BY t1.`soft_name`\nORDER BY ipAssetNumber DESC\nLIMIT 20',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'30%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5,title:\"资产常用组件TOP20\"}','colorgroup1','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 15:21:35','super','2024-04-07 14:15:33','100','1','100',NULL,'',0,NULL,0),('202211091607186290001','S-000361','资产全景-数据库类型TOP20','table','sql','','SELECT\n  t1.soft_name AS softName, \n  t1.new_soft_name AS newSoftName,\n  COUNT(DISTINCT t1.`ip`) AS ipAssetNumber\nFROM\n  (SELECT\n    pivot.value AS soft_name,\n    pivot.name AS new_soft_name,\n    ip\n  FROM\n    tb_asset_software\n    INNER JOIN\n    (SELECT \'server\' AS `name`, \'SQL Server\' AS `value`\n    UNION ALL\n    SELECT \'db2\' AS `name`, \'DB2\' AS `value`\n    UNION ALL\n    SELECT \'postgre\' AS `name`, \'Postgre\' AS `value`\n    UNION ALL\n    SELECT \'mysql\' AS `name`, \'MySQL\' AS `value`\n    UNION ALL\n    SELECT \'redis\' AS `name`, \'Redis\' AS `value`\n    UNION ALL\n    SELECT \'oracle\' AS `name`, \'Oracle\' AS `value`\n    UNION ALL\n    SELECT \'mongo\' AS `name`, \'Mongodb\' AS `value`\n    UNION ALL\n    SELECT \'sybase\' AS `name`, \'Sybase\' AS `value`\n    UNION ALL\n    SELECT \'memcache\' AS `name`, \'Memcache\' AS `value`\n    UNION ALL\n    SELECT \'elastic\' AS `name`, \'ElasticSearch\' AS `value`\n    UNION ALL\n    SELECT \'hbase\' AS `name`, \'HBase\' AS `value`) AS pivot ON soft_name LIKE CONCAT(\'%\', pivot.name,\'%\')\n  WHERE second_cat_tag = \'数据库系统\') t1\n  INNER JOIN tb_asset t2 ON t1.`ip` = t2.`internal_ip`\n  INNER JOIN\n    (SELECT\n      ta.`id`\n    FROM\n      tb_asset ta\n    WHERE ta.`del_flag` = \'0\' \n      AND ta.`dept_path` LIKE \'%,99%\'\n      AND 100 = \'${deptId<\'\'>}\'\n    UNION\n    SELECT\n      ta.`id`\n    FROM\n      tb_asset ta\n      INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n    WHERE sd.`del_flag` = \'0\'\n      AND ta.`del_flag` = \'0\'\n      AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n      $[AND ta.`affiliation_dept_node_id` IN (${authDeptIdStr})]$\n  ) t3 ON t2.`id` = t3.`id`\nGROUP BY t1.`soft_name`\nORDER BY ipAssetNumber DESC\nLIMIT 20',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5}','colorgroup17','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 16:07:19','super','2023-08-12 09:48:26','100','1','100',NULL,'',1,NULL,0),('202211091618363130002','S-000361','资产全景-数据库类型TOP20_副本','table','sql','','SELECT\n  t1.soft_name AS softName, \n  COUNT(t2.`id`) AS ipAssetNumber\nFROM\n  (SELECT\n    CASE\n      WHEN soft_name LIKE \'%server%\'\n      THEN \'SQL Server\'\n      WHEN soft_name LIKE \'%db2%\'\n      THEN \'DB2\'\n      WHEN soft_name LIKE \'%postgre%\'\n      THEN \'Postgre\'\n      WHEN soft_name LIKE \'%mysql%\'\n      THEN \'MySQL\'\n      WHEN soft_name LIKE \'%redis%\'\n      THEN \'Redis\'\n      WHEN soft_name LIKE \'%oracle%\'\n      THEN \'Oracle\'\n      WHEN soft_name LIKE \'%mongo%\'\n      THEN \'Mongodb\'\n      WHEN soft_name LIKE \'%sybase%\'\n      THEN \'Sybase\'\n      WHEN soft_name LIKE \'%memcache%\'\n      THEN \'Memcache\'\n      WHEN soft_name LIKE \'%elastic%\'\n      THEN \'ElasticSearch\'\n      WHEN soft_name LIKE \'%hbase%\'\n      THEN \'HBase\'\n      ELSE soft_name\n    END AS soft_name,\n    ip\n  FROM\n    tb_asset_software\n  WHERE second_cat_tag = \'数据库系统\') t1\n  INNER JOIN tb_asset t2 ON t1.`ip` = t2.`internal_ip`\n  INNER JOIN\n    (SELECT\n      ta.`id`\n    FROM\n      tb_asset ta\n    WHERE ta.`dept_path` LIKE \'%,99%\'\n      AND ta.`del_flag` = \'0\'\n      AND 100 = \'${deptId<\'\'>}\'\n    UNION\n    SELECT\n      ta.`id`\n    FROM\n      tb_asset ta\n      INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n    WHERE FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n      AND sd.`del_flag` = \'0\'\n      AND ta.`del_flag` = \'0\') t3\n    ON t2.`id` = t3.`id`\nGROUP BY t1.`soft_name`\nORDER BY ipAssetNumber DESC\nLIMIT 20',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 16:18:36','super','2022-11-09 16:18:36','100','0','100',NULL,NULL,NULL,NULL,NULL),('202211091704118290000','S-000362','资产全景-资产来源分布','table','sql','','select\n  sda.`dict_value` as sourceId,\n  sda.`dict_label` as sourceName,\n  tt.ipAssetNumber\nfrom\n  (SELECT\n    t1.`source`,\n    count(1) as ipAssetNumber\n  FROM\n    tb_asset t1\n    INNER JOIN\n      (SELECT\n        ta.`id`\n      FROM\n        tb_asset ta\n      WHERE ta.`del_flag` = \'0\'\n        AND ta.`dept_path` LIKE \'%,99%\' \n        AND 100 = \'${deptId<\'\'>}\'\n      UNION\n      SELECT\n        ta.`id`\n      FROM\n        tb_asset ta\n        INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n      WHERE sd.`del_flag` = \'0\'\n        AND ta.`del_flag` = \'0\'\n        AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n        $[AND ta.`affiliation_dept_node_id` IN (${authDeptIdStr})]$    \n    ) t2 ON t1.`id` = t2.`id`\n  GROUP BY t1.`source`) tt\n  inner join sys_dict_data sda on tt.`source` = sda.`dict_value` and sda.`dict_type` = \'asset_ip_source\'\nwhere sda.`status` = \'0\'\nORDER BY ipAssetNumber DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"30%\", \"40%\"],\"legendRight\":\"5%\",\"showNum\":5}','colorgroup10','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 17:04:12','super','2023-08-12 09:48:37','100','1','100',NULL,'',0,NULL,0),('202211091853595530000','S-000363','资产全景-各单位资产分布','table','sql','','SELECT\n  tt.deptId,\n  tt.deptName,\n  tt.ipAssetNumber\nFROM\n  (SELECT\n    \'99\' AS deptId,\n    IF(ta.`dept_path` LIKE \'%,99%\', \'无归属资产\', NULL) AS deptName,\n    COUNT(1) AS ipAssetNumber\n  FROM\n    tb_asset ta\n  WHERE ta.`dept_path` LIKE \'%,99%\'\n    AND ta.`del_flag` = \'0\'\n    AND 100 = \'${deptId<\'\'>}\'\n  union all  \n  SELECT\n    sd.`dept_id` AS deptId,\n    sd.`dept_name` AS deptName,\n    COUNT(ta.id) AS ipAssetNumber\n   FROM\n     tb_asset ta\n     INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n   where ta.`del_flag` = \'0\'\n     AND sd.`del_flag` = \'0\'\n     AND 100 <> \'${deptId<\'\'>}\' \n     AND ta.`affiliation_dept_node_id` = \'${deptId<\'\'>}\'\n  UNION ALL\n  SELECT\n    t1.`dept_id` AS deptId,\n    t1.`dept_name` AS deptName,\n    COUNT(t2.id) AS ipAssetNumber\n  FROM\n    sys_dept t1\n    INNER JOIN\n      (SELECT\n        ta.`id`,\n        CONCAT(sd.ancestors, \',\', sd.`dept_id`) AS ancestors\n      FROM\n        tb_asset ta\n        INNER JOIN sys_dept sd ON ta.`affiliation_dept_node_id` = sd.`dept_id`\n      WHERE sd.`del_flag` = \'0\'\n        AND ta.`del_flag` = \'0\'\n        AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n        $[AND ta.`affiliation_dept_node_id` IN (${authDeptIdStr})]$\n    ) t2 ON FIND_IN_SET(t1.`dept_id`, t2.ancestors)\n  WHERE t1.`parent_id` = \'${deptId<\'\'>}\'\n    AND t1.`del_flag` = \'0\'\n  GROUP BY t1.`dept_name`) tt\nWHERE NOT ISNULL(tt.deptName)\nORDER BY tt.ipAssetNumber DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 18:54:00','super','2023-08-12 09:48:57','100','1','100',NULL,'',1,NULL,0),('202211091913586510005','S-000365','资产全景-应用系统总数、发布互联网系统数、关基系统数、核心系统数','table','sql','','SELECT\n  count(taas.id) as appAssetNumber,\n  \'0\' as isPublishInternet,\n  IFNULL(sum(taas.`is_publish_internet` = \'0\'), 0) as pubAppAssetNumber,\n  \'0\' as isCriticalInfrastructure,\n  IFNULL(sum(taas.`is_critical_infrastructure` = \'0\'), 0) as criticalAppAssetNumber,\n  \'2\' as sysLevel,\n  IFNULL(sum(taas.`sys_level` = \'2\'), 0) as levelAppAssetNumber\nFROM\n  tb_asset_app_system taas\n  INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\nWHERE sd.`del_flag` = \'0\'\n  AND taas.`del_flag` = \'0\'\n  AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n  $[AND taas.`dept_id` IN (${authDeptIdStr})]$',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 19:13:59','super','2023-08-12 09:49:26','100','1','100',NULL,'',1,NULL,0),('202211091924024840006','S-000366','资产全景-在用系统','text-progress','sql','','SELECT\n  tt.statusAppAssetNumber AS 在用系统,\n  CASE\n    WHEN ( tt.statusAppAssetNumber / tt.appAssetNumber * 10000 ) < 1\n    THEN CEILING( tt.statusAppAssetNumber / tt.appAssetNumber * 10000 ) / 100\n    ELSE FLOOR( tt.statusAppAssetNumber / tt.appAssetNumber * 10000 ) / 100\n  END AS 在用系统率,\n  \'0\' as sysStatus\nFROM(\nSELECT\n  COUNT(taas.id) AS appAssetNumber,\n  SUM(taas.`sys_status` = \'0\') AS statusAppAssetNumber\nFROM\n  tb_asset_app_system taas\n  INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\nWHERE sd.`del_flag` = \'0\'\n  AND taas.`del_flag` = \'0\'\n  AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n  $[AND taas.`dept_id` IN (${authDeptIdStr})]$\n) tt',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"在用系统\",\"num\":1},{\"key\":\"在用系统率\",\"num\":2}]}','singleYellow','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-09 19:24:02','super','2023-08-12 09:49:46','100','1','100',NULL,'',0,NULL,0),('202211101639349660022','S-000367','资产全景-系统等级分布','annular','sql','','SELECT\n  COUNT(taas.id) AS count,\n  taas.`sys_level_label` AS name,\n  taas.`sys_level` AS sysLevel\nFROM\n  tb_asset_app_system taas\n  INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\nWHERE sd.`del_flag` = \'0\'\n  AND taas.`del_flag` = \'0\'\n  AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n  $[AND taas.`dept_id` IN (${authDeptIdStr})]$\nGROUP BY taas.`sys_level_label`',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5}','westeros','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-10 16:39:35','super','2023-08-12 09:50:32','100','1','100',NULL,'',0,NULL,0),('202211101647047020000','S-000368','资产全景-系统状态分布','annular','sql','','SELECT\n  COUNT(taas.id) AS count,\n  taas.`sys_status_label` AS name,\n  taas.`sys_status` AS sysStatus\nFROM\n  tb_asset_app_system taas\n  INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\nWHERE sd.`del_flag` = \'0\'\n  AND taas.`del_flag` = \'0\'\n  AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n  $[AND taas.`dept_id` IN (${authDeptIdStr})]$\nGROUP BY taas.`sys_status_label`',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5}','colorgroup10','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-10 16:47:05','super','2023-08-12 09:50:41','100','1','100',NULL,'',0,NULL,0),('202211101651272940006','S-000369','资产全景-系统类型分布','annular','sql','','SELECT\n  COUNT(taas.id) AS count,\n  taas.`sys_type_label` AS name,\n  taas.`sys_type` AS sysType\nFROM\n  tb_asset_app_system taas\n  INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\nWHERE sd.`del_flag` = \'0\'\n  AND taas.`del_flag` = \'0\'\n  AND FIND_IN_SET( \'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`) )\n  $[AND taas.`dept_id` IN (${authDeptIdStr})]$\nGROUP BY taas.`sys_type_label`',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",\"showNum\":5}','colorgroup17','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-10 16:51:27','super','2023-08-12 09:50:52','100','1','100',NULL,'',0,NULL,0),('202211101701297760012','S-000370','资产全景-各单位应用系统分布','table','sql','','SELECT\n    tt.dept_id AS `deptId`,\n    tt.dept_name AS `deptName`,\n    COUNT(tt.id) AS `appSysNumber`,\n    SUM(tt.safety_score < 90) AS `notSafeAppSysNumber`\n  FROM\n    (SELECT\n      sd.`dept_id`,\n      sd.`dept_name`,\n      taas.id,\n      IFNULL(AVG(ta.safety_score), 100) AS safety_score\n    FROM\n      tb_asset_app_system taas\n      INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\n      LEFT JOIN tb_app_system_relation_asset tasra ON taas.id = tasra.app_system_id AND tasra.`del_flag` = \'0\'\n      LEFT JOIN tb_asset ta ON tasra.`asset_id` = ta.`id` AND ta.`del_flag` = \'0\'\n    WHERE taas.`dept_id` = \'${deptId<\'\'>}\'\n      AND sd.`del_flag` = \'0\'\n      AND taas.`del_flag` = \'0\'\n    GROUP BY taas.id\n    UNION\n    SELECT\n      t1.`dept_id`,\n      t1.`dept_name`,\n      t2.id,\n      t2.safety_score\n    FROM\n      sys_dept t1\n      INNER JOIN\n        (SELECT\n          taas.`id`,\n          CONCAT(sd.ancestors, \',\', sd.`dept_id`) AS ancestors,\n          IFNULL(AVG(ta.safety_score), 100) AS safety_score\n        FROM\n          tb_asset_app_system taas\n          INNER JOIN sys_dept sd ON taas.`dept_id` = sd.`dept_id`\n          LEFT JOIN tb_app_system_relation_asset tasra ON taas.id = tasra.app_system_id AND tasra.`del_flag` = \'0\'\n          LEFT JOIN tb_asset ta ON tasra.`asset_id` = ta.`id` AND ta.`del_flag` = \'0\'\n        WHERE sd.`del_flag` = \'0\'\n          AND taas.`del_flag` = \'0\'\n          AND FIND_IN_SET(\'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`))\n          $[AND taas.`dept_id` IN (${authDeptIdStr})]$\n        GROUP BY taas.`id`) t2 ON FIND_IN_SET(t1.`dept_id`, t2.ancestors)\n    WHERE t1.`del_flag` = \'0\'\n      AND t1.`parent_id` = \'${deptId<\'\'>}\'\n  ) tt\n  GROUP BY tt.dept_id\n  ORDER BY `appSysNumber` DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','','blueYellow','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-10 17:01:30','super','2023-08-12 09:51:06','100','1','100',NULL,'',1,NULL,0),('202211101921158260006','S-000567','表格测试用例','table','static','','[\n    {\n        \"COUNT\": 57.4468,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润信托\"\n    },\n    {\n        \"COUNT\": 36.6667,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润万家\"\n    },\n    {\n        \"COUNT\": 31.6667,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润医疗\"\n    },\n    {\n        \"COUNT\": 30.4348,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润资产\"\n    },\n    {\n        \"COUNT\": 27.2727,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润资本\"\n    },\n    {\n        \"COUNT\": 19.5,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润双鹤\"\n    },\n    {\n        \"COUNT\": 17.1429,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润环保\"\n    },\n    {\n        \"COUNT\": 16.0179,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润江中\"\n    },\n    {\n        \"COUNT\": 15,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润五丰\"\n    },\n    {\n        \"COUNT\": 13.9286,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润银行\"\n    },\n    {\n        \"COUNT\": 13.8462,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润医药\"\n    },\n    {\n        \"COUNT\": 9.1954,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润物业\"\n    },\n    {\n        \"COUNT\": 8.7719,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润化学材料\"\n    },\n    {\n        \"COUNT\": 7.83,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润电力\"\n    },\n    {\n        \"COUNT\": 7.4627,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润金融\"\n    },\n    {\n        \"COUNT\": 6.187,\n        \"CHILD\": \"中招率\",\n        \"NAME\": \"华润置地\"\n    },\n    {\n        \"COUNT\": 5