 is not null\n  AND tt.dept_name != \'\'\nGROUP BY dept_name\nORDER BY riskAvgNumber DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-16 18:57:23','super','2023-09-21 14:22:51','100','1','100',NULL,'',0,NULL,0),('202211171102023000000','S-000389','一维数据折线图下钻面板主表','line','sql','','SELECT problem_big_category AS NAME, COUNT(1) AS COUNT FROM `tb_custom_risk_assessment_approval` GROUP BY problem_big_category;',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-17 11:02:02','super','2022-11-17 14:41:50','100','1','100','2','202211171112531060004',1,NULL,1),('202211171110466010002','S-000390','一维数据折线图下钻关联表','line','sql','','SELECT problem_small_category AS NAME, COUNT(1) AS COUNT FROM `tb_custom_risk_assessment_approval` WHERE 1=1 \n and problem_big_category  = \'${name<1>}\'   GROUP BY problem_small_category;',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-17 11:10:47','super','2022-11-17 14:42:23','100','1','100',NULL,NULL,1,NULL,1),('202211171442315540005','S-000389','二维数据折线图下钻面板主表','line','sql','','SELECT problem_big_category AS NAME, problem_small_category AS child, COUNT(1) AS COUNT FROM `tb_custom_risk_assessment_approval` GROUP BY problem_big_category,problem_small_category;\n',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2022-11-17 14:42:32','super','2022-11-17 16:23:27','100','1','100','2','202211171454319440007',1,NULL,1),('202211171445244260006','S-000390','二维数据折线图下钻关联表','line','sql','','SELECT COUNT(1) AS COUNT, problem_big_category AS NAME , problem_small_category AS child FROM `tb_custom_r