umber,\n    IFNULL(SUM(t.`safety_score` < 90), 0) AS notSafeAppSysNumber\n  FROM\n    (SELECT\n      t1.id,\n      IFNULL(AVG(ta.safety_score), 100) AS safety_score\n    FROM\n      tb_asset_app_system t1\n      INNER JOIN sys_dept sd ON t1.`dept_id` = sd.`dept_id`\n      LEFT JOIN tb_app_system_relation_asset tasra ON t1.id = tasra.app_system_id AND tasra.`del_flag` = \'0\'\n      LEFT JOIN tb_asset ta ON tasra.`asset_id` = ta.`id` AND ta.`del_flag` = \'0\'\n    WHERE FIND_IN_SET(\'${deptId<\'\'>}\', CONCAT(sd.ancestors, \',\', sd.`dept_id`))\n      AND t1.`del_flag` = \'0\'\n      AND sd.`del_flag` = \'0\'\n    GROUP BY t1.id) t) tt',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"带病系统\",\"num\":1},{\"key\":\"带病系统率\",\"num\":2}]}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,'','super','管理员','2022-12-14 17:40:22','super','2022-12-14 17:40:22','100','0','100','0','',1,NULL,0),('202212141745441620027','S-000406','测试关联url','line','sql','','1',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','','colorgroup16','','1','1','4','3',NULL,0,'',NULL,'','super','管理员','2022-12-14 17:45:44','super','2022-12-14 17:45:44','100','0','100','3','https://std_stp_dev.crc.com.cn/',1,NULL,2),('202212151404012840011','S-000407','jxq_test','line','sql','','aaa',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','','colorgroup16','','1','1','4','3',NULL,0,'',NULL,'','super','管理员','2022-12-15 14:04:01','super','2022-12-15 14:04:01','100','0','100','0','',1,NULL,0),('202212151537005840019','S-000409','123','line','sql','','123',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','123','colorgroup16','','1','1','4','3',NULL,0,'',NULL,'123','super','管理员','2022-12-15 15:37:01','super','2022-12-15 15:37:01','100','1','100','','',1,NULL,0),('202212151538067660020','S-000410','123123','line','sql','','123',NULL,'{\"timeType