N tb_fish_task_bu_info t ON e.task_id = t.task_id AND FIND_IN_SET( t.bu_id, e.bu_tree_id)\nWHERE t.task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" AND t.bu_id = \"${deptId<100>}\" AND e.type = 3',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"点击链接人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','blue','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-04-26 22:27:44','super','2023-04-27 13:55:52','100','1','100','','',1,NULL,0),('202304271417088390000','S-000605','钓鱼邮件-BU单位-各部门中招情况','bar','sql','','(\n  SELECT a.dept_name AS NAME , IFNULL(a.capCount, 0)/b.num_of_send * 100 AS COUNT, \'中招率\' AS CHILD FROM (\n    SELECT sd.`dept_id`, sd.`dept_name`, IFNULL(sum(tfte.capCount), 0 ) as capCount\n    FROM sys_dept sd \n      LEFT JOIN (\n        SELECT COUNT( DISTINCT(e.email) ) AS capCount,e.bu_tree_id, e.bu_name, e.task_id FROM tb_fish_target_emploree e \n          WHERE e.task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" GROUP BY e.bu_tree_id\n      ) tfte\n     ON FIND_IN_SET(sd.`dept_id`, tfte.`bu_tree_id`)\n    WHERE sd.`parent_id` = \"${deptId<100>}\" \n    GROUP BY sd.`dept_id` \n  ) a\n  LEFT JOIN ( SELECT total, num_of_send, bu_id, bu_name FROM `tb_fish_task_bu_info` )  b\n  ON b.bu_id = a.dept_id\n)\n\nUNION\n\n(\n\n  SELECT a.dept_name AS NAME , IFNULL(a.capCount, 0 ) AS COUNT, \'中招人数\' AS CHILD FROM (\n  SELECT sd.`dept_id`, sd.`dept_name`, IFNULL(sum(tfte.capCount), 0 ) as capCount\n  FROM sys_dept sd \n  LEFT JOIN (\n     SELECT COUNT( DISTINCT(e.email) ) AS capCount,e.bu_tree_id, e.bu_name, e.task_id FROM tb_fish_target_emploree e \n      WHERE e.task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" GROUP BY e.bu_tree_id\n      ) tfte\n    ON FIND_IN_SET(sd.`dept_id`, tfte.`bu_tree_id`)\n   WHERE sd.`parent_id` = \"${deptId<100>}\" \n   GROUP BY sd.`dept_id` \n  ) a\n  LEFT JOIN ( SELECT total, num_of_send, bu_id, bu_name FROM `tb_fish_task_bu_info` )  b\n  ON b.bu_id = a.dept_id\n)',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{legendData:[\"中招人数\",\"中招率\"],\"yTwoAxisUnit\":\"%\",\"yTwoAxisLegend\":\"中招率\",\"labelPosition\":\"top\",\"labelFontSize\":11,\"legendDataColor\":{\"中招人数\":\"#71a3f3\",\"中招率\":\"#ffc836\"},\"barGap\":\"100%\",\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2}],\"dataOrder\":{\"field\":\"中招率\",\"sort\":\"desc\"}}','blueYellow','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-04-27 14:17:09','super','2023-05-05 14:24:39','100','1','100','','',1,NULL,0),('20230427141924870001','S-000606','钓鱼邮件-BU单位-中招高峰时间分布','area','sql','','( SELECT COUNT( DISTINCT(email) ) AS COUNT , \'点击链接人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM tb_fish_target_emploree \nWHERE task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" AND FIND_IN_SET( \"${deptId<100>}\" , bu_tree_id) AND type = 3 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(email) ) AS COUNT , \'点击附件人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM tb_fish_target_emploree \nWHERE task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" AND FIND_IN_SET( \"${deptId<100>}\" , bu_tree_id)  AND type = 2 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\nORDER BY NAME ASC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'blueYellow','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-04-27 14:19:24','super','2023-04-27 17:44:13','100','1','100','','',1,NULL,0),('202304271420157430002','S-000607','钓鱼邮件-BU单位-中招率趋势','line','sql','','SELECT cap_rate AS COUNT, cap_name AS NAME FROM (\nSELECT c.*, CONCAT(LEFT(a.cap_start, 4),\'年\',\nSUBSTRING(a.cap_start, 6,2),\'年\',\'(\', \nREPLACE(SUBSTRING(a.cap_start, 6,5),\'-\',\'.\'), \'-\', \nREPLACE(SUBSTRING(a.cap_end, 6,5),\'-\',\'.\'), \')\') AS cap_name FROM tb_fish_task_cap c\nLEFT JOIN tb_fish_task_group_info a ON a.`task_id` = c.`task_id`\n\n WHERE c.cap_start <= \n   ( \n      SELECT cap_start FROM tb_fish_task_cap  WHERE task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\"  AND bu_id = \"${deptId<100>}\"\n   )  \n  AND c.bu_id = \"${deptId<100>}\"\nORDER BY cap_start DESC LIMIT 0,5 ) AS t ORDER BY t.cap_start ASC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":\"中招率\",\"yAxisUnit\":\"%\",\"xaxisLabelRotate\":30}','singleBlue','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-04-27 14:20:16','super','2023-04-27 17:45:49','100','1','100','','',1,NULL,0),('202304271423032180003','S-000608','钓鱼邮件-BU单位-中招详情','table','sql','','SELECT bu_name AS \'部门\', name AS \'姓名\', email AS \'邮箱\',  IF(MAX(isfile),\'是\',\'否\') AS \'是否打开附件\' ,\n      IF(MAX(islink),\'是\',\'否\') AS \'是否点击链接\'  , min(cap_time) AS \'中招时间\'\n   FROM ( \n	SELECT bu_name, name, email ,IF(type=2, 1, 0) AS isfile, IF(type=3,1,0) AS islink , cap_time\n	FROM tb_fish_target_emploree WHERE task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" AND FIND_IN_SET( \"${deptId<100>}\" , bu_tree_id) ORDER BY cap_time DESC LIMIT 0,10000000 \n   ) a GROUP BY email ORDER BY MIN(cap_time) DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"部门\",\"field\":\"部门\"},{\"name\":\"姓名\",\"field\":\"姓名\"},{\"name\":\"邮箱\",\"field\":\"邮箱\"},{\"name\":\"是否打开附件\",\"field\":\"是否打开附件\"},{\"name\":\"是否点击链接\",\"field\":\"是否点击链接\"},{\"name\":\"中招时间\",\"field\":\"中招时间\"}]}','blue','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-04-27 14:23:03','super','2023-04-27 17:26:58','100','1','100','','',1,NULL,0),('202304271441371470004','S-000609','钓鱼邮件-BU单位-各部门中招数据','table','sql','','SELECT @rownum:=@rownum+1 AS \'排名\' , t.* FROM ( SELECT a.dept_name AS \'部门\' , IFNULL( t.total, 0 ) AS \'邮件发送数\', \nIFNULL( t.num_of_send, 0 ) AS \'邮件送达数\', IFNULL(capCount, 0 ) AS \'中招人数\',\nIFNULL(IFNULL(capCount, 0)/t.num_of_send * 100, 0) AS \'中招率\', \nIFNULL(openCount, 0) AS \'打开附件人数\', \nIFNULL(IFNULL(openCount, 0)/t.num_of_send * 100, 0) AS \'附件打开率\',  \nIFNULL(linkCount, 0) AS \'点击链接人数\', \nIFNULL(IFNULL(linkCount, 0)/t.num_of_send * 100, 0) AS \'链接点击率\'\nFROM (\n    SELECT sd.`dept_id`, sd.`dept_name`, IFNULL(sum(tfte.capCount), 0 ) as capCount , IFNULL(sum(tfte.openCount), 0 ) as openCount, IFNULL(sum(tfte.linkCount), 0 ) as linkCount, tfte.task_id\n    FROM sys_dept sd \n      LEFT JOIN (\n        SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.bu_tree_id, e.bu_name, e.task_id, \n        SUM(e.type = 2) openCount , SUM(e.type = 3) linkCount\n        FROM tb_fish_target_emploree  e \n          WHERE e.task_id = \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\" GROUP BY e.bu_tree_id\n      ) tfte\n     ON FIND_IN_SET(sd.`dept_id`, tfte.`bu_tree_id`)\n    WHERE sd.`parent_id` = \"${deptId<100>}\" \n    GROUP BY sd.`dept_id` ) a \nLEFT JOIN (select * from tb_fish_task_bu_info where  \"${taskId<10f9e8bf8cd92405b5ff1ff851c892ee>}\") t\n    ON a.task_id = t.task_id AND a.dept_id = t.bu_id\nORDER BY 中招率 DESC ) t, (SELECT @rownum:=0) r',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"排名\",\"field\":\"排名\"},{\"name\":\"部门\",\"field\":\"部门\"},{\"name\":\"邮件发送数\",\"field\":\"邮件发送数\"},{\"name\":\"邮件送达数\",\"field\":\"邮件送达数\"},{\"name\":\"中招人数\",\"field\":\"中招人数\"},{\"name\":\"中招率\",\"field\":\"中招率\"},{\"name\":\"打开附件人数\",\"field\":\"打开附件人数\"},{\"name\":\"附件打开率\",\"field\":\"附件打开率\"},{\"name\":\"点击链接人数\",\"field\":\"点击链接人数\"},{\"name\":\"链接点击率\",\"field\":\"链接点击率\"}],\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"附件打开率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"链接点击率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"}]}','blue','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-04-27 14:41:37','super','2023-05-05 14:25:41','100','1','100','','',1,NULL,0),('202305241447086840000','