ngs\": {},\n                                        \"_source\": {\n                                                \"excludes\": []\n                                        },\n                                        \"query\": {\n                                                \"bool\": {\n                                                        \"must\": [],\n                                                        \"filter\": [{\n                                                                \"range\": {\n                                                                        \"SparkTime\": {\n                                                                                \"gte\": dateStart,\n                                                                                \"lte\": dateEnd,\n                                                                                \"format\": \"strict_date_optional_time\"\n                                                                        }\n                                                                }\n                                                        }],\n                                                        \"should\": [],\n                                                        \"must_not\": []\n                                                }\n                                        }\n                                }',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"1440\"}','{\"tableHeader\":[{\"name\":\"设备IP\",\"field\":\"name\"},{\"name\":\"设备名称\",\"field\":\"child\"},{\"name\":\"近24小时日志量\",\"field\":\"count\"}]}','blue','2','1','1','4','3',NULL,0,'sec_all*',NULL,NULL,'super','管理员','2023-06-07 20:46:38','super','2023-11-24 17:41:10','100','1','100','','',1,NULL,0),('202306082242124240001','S-000593','[HZQ测试] 安全告警总数','count','sql','','SELECT FORMAT(count(*) , 0 ) AS COUNT FROM tb_alarm_report',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"安全告警总数\"}','colorgroup16','','1','1','4','3','/profile/upload/2023/06/08/202306082241019990000.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:42:12','super','2023-06-08 22:42:12','100','1','100','','',1,NULL,0),('20230608224305300003','S-000594','[HZQ测试] 未归档告警数量','count','sql','','SELECT IFNULL(count(*) , 0 ) AS COUNT FROM tb_alarm_report \nWHERE order_status IN (\'研判\',\'处置\',\'审核\') AND del_flag= 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"未归档告警数量\"}','colorgroup16','','1','1','4','3','/profile/upload/2023/06/08/202306082243016020002.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:43:05','super','2023-06-08 22:43:05','100','1','100','','',1,NULL,0),('202306082243572030005','S-000595','[HZQ测试] 重点关注告警数量','count','sql','','SELECT IFNULL(count(1) , 0 ) AS COUNT FROM tb_alarm_report \nWHERE focus_tag = 1 AND del_flag= 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"重点关注告警数量\"}','colorgroup16','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:43:57','super','2023-06-08 22:43:57','100','1','100','','',1,NULL,0),('202306082244146810006','S-000596','[HZQ测试] 已失陷工单数量','count','sql','','SELECT IFNULL(count(1) , 0 ) AS COUNT FROM tb_alarm_report \nWHERE attack_result_label = \'已失陷\' AND del_flag= 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"已失陷工单数量\"}','colorgroup16','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:44:15','super','2023-06-08 22:44:15','100','1','100','','',1,NULL,0),('202306082245153460007','S-000597','[HZQ测试] 安全告警趋势（近30天）','area','sql','','SELECT COUNT(1) AS COUNT,DATE_FORMAT(alarm_time, \'%Y-%m-%d\') AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND  DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd GROUP BY DATE_FORMAT(alarm_time, \'%Y-%m-%d\') ORDER BY NAME ASC',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"labelPosition\":\"top\",\"gridBottom\":\"8%\",\"areaColor\":\"#B3DEFF\",\"legendData\":\"安全告警数量\",\"smooth\":true,\"xaxisLabelRotate\":0,\"dataFillUp\":{\"dataType\":\"date\",\"interval\":\"day\",\"dateFormat\":\"yyyy-MM-dd\",\"dataRange\":[\"dateStart\",\"dateEnd\"],\"fillData\":0}}','blue','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:45:15','super','2023-06-08 22:45:15','100','1','100','','',1,NULL,0),('202306082248005590008','S-000598','[HZQ测试] 待处置告警（近30天）','table','sql','','SELECT \nDATE_FORMAT(alarm_time, \'%Y-%m-%e %H:%i:%s\') AS 告警时间, \nduty_dept_name AS 责任部门, \nattack_ip AS 攻击IP, \nvictimized_ip AS 受害IP, \ntitle AS 告警标题 \nFROM tb_alarm_report \nWHERE order_status = \'处置\' \nAND alarm_time BETWEEN dateStart AND dateEnd \nORDER BY alarm_time DESC',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"tableHeader\":[{\"name\":\"告警时间\",\"field\":\"告警时间\"},{\"name\":\"责任部门\",\"field\":\"责任部门\"},{\"name\":\"攻击IP\",\"field\":\"攻击IP\"},{\"name\":\"受害IP/URL\",\"field\":\"受害IP\"},{\"name\":\"告警标题\",\"field\":\"告警标题\"}]}','colorgroup16','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:48:01','super','2023-06-08 22:48:01','100','1','100','','',1,NULL,0),('202306082248472350009','S-000599','[HZQ测试] 告警类型分布（TOP20/近30天）','annular','sql','','SELECT COUNT(1) AS COUNT, title AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND create_time BETWEEN dateStart AND dateEnd \nGROUP BY title ORDER BY COUNT DESC LIMIT 0, 20',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"legendNum\":6,\"showNum\":true}','colorgroup1','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:48:47','super','2023-06-08 22:48:47','100','1','100','','',1,NULL,0),('202306082249069020010','S-000600','[HZQ测试] 告警攻击结果分布（近30天）','annular','sql','','(\n        SELECT COUNT(1) AS COUNT,  \'已失陷\' AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND attack_result_label = \'已失陷\' AND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd \n) UNION (\n        SELECT COUNT(1) AS COUNT,  \'疑似失陷\' AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND attack_result_label = \'疑似失陷\' AND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd \n) UNION (\n        SELECT COUNT(1) AS COUNT,  \'攻击成功\' AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND attack_result_label = \'攻击成功\' AND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd \n)UNION (\n        SELECT COUNT(1) AS COUNT,  \'疑似成功\' AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND attack_result_label = \'疑似成功\' AND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd \n) UNION (\n        SELECT COUNT(1) AS COUNT,  \'企图\' AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND attack_result_label = \'企图\' AND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd \n) UNION (\n        SELECT COUNT(1) AS COUNT,  \'失败\' AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND attack_result_label = \'失败\' AND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd \n)',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"center\":[\'40%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"5%\",legendData:[\"已失陷\",\"疑似失陷\",\"攻击成功\",\"疑似成功\",\"企图\",\"失败\"],\"legendDataColor\":{\"已失陷\":\"#D06773\",\"疑似失陷\":\"#FFA39E\",\"攻击成功\":\"#FFC5B8\",\"疑似成功\":\"#FFCA8F\",\"企图\":\"#C5C0FF\",\"失败\":\"#CAD0DF\"},\"showNum\":true}','colorgroup1','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:49:07','super','2023-06-08 22:49:07','100','1','100','','',1,NULL,0),('202306082249318180011','S-000601','[HZQ测试] 告警攻击手段分布（近30天）','annular','sql','','SELECT COUNT(1) AS COUNT, attack_means AS NAME FROM tb_alarm_report WHERE del_flag= 0 AND  create_time BETWEEN dateStart AND dateEnd \nGROUP BY attack_means',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"center\":[\'35%\', \'50%\'],\"radius\":[\"40%\", \"50%\"],\"legendRight\":\"2%\",\"showNum\":true,\"legendNum\":12}','colorgroup17','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:49:32','super','2023-06-08 22:49:32','100','1','100','','',1,NULL,0),('202306082250114320012','S-000602','[HZQ测试] 各部门告警处置效率','bar','sql','','SELECT duty_dept_name AS name, count(*) AS count, \'已归档告警数\' AS child FROM tb_alarm_report \nWHERE duty_dept_name != \'\' AND order_status = \'归档\'   AND del_flag= 0\nGROUP BY duty_dept_name \nUNION \n(SELECT duty_dept_name AS name, \nround(AVG(TIMESTAMPDIFF(HOUR, create_time, update_time)), 1) AS count , \'平均闭环时数\' AS child FROM tb_alarm_report WHERE  duty_dept_name != \'\' AND order_status = \'归档\'  AND del_flag= 0\nGROUP BY duty_dept_name)',NULL,'{\"timeType\":\"2\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"43200\"}','{\"yTwoAxisLegend\":\"平均闭环时数\",\"yTwoAxisUnit\":\"h\",\"labelPosition\":\"top\",\"labelFontSize\":12,\"xAxisNum\":8,\"dataOrder\":{\"field\":\"已归档告警数\",\"sort\":\"desc\"}}','colorgroup10','','1','1','4','3','/profile/upload/2023/06/08/202306082243549980004.png',0,'',NULL,NULL,'super','管理员','2023-06-08 22:50:11','super','2023-06-08 22:50:11','100','1','100','','',1,NULL,0),('202306121118023440001','S-000603','[SZC安全运营中心] 资产概览','table','sql','','SELECT \n COUNT(*) AS assetTotal,\n (SELECT COUNT(*) FROM   (SELECT a.* FROM tb_asset a LEFT JOIN tb_asset_person p ON a.id = p.asset_id AND p.type = 1 \nWHERE  operating_status = \'1\' AND\n            (\n                a.affiliation_dept_name IS NULL\n                OR a.affiliation_dept_name = \'\'\n                OR a.affiliation_dept_node_id IS NULL\n                OR a.affiliation_dept_node_id = \'\'\n                OR p.id IS NULL\n                OR (p.user_name IS NULL AND p.type = 1 )\n                OR (p.user_name = \'\' AND p.type = 1 )\n            )\n            AND (a.apply = \'0\' OR a.apply IS NULL OR a.apply = \'\')\n            AND a.del_flag = \'0\' GROUP BY a.internal_ip )t ) AS unCreditedAssetTotal,\n \n (SELECT COUNT(*) FROM tb_asset_app_system  WHERE del_flag = 0 ) AS appAssetTotal ,\n \n  (SELECT COUNT(*) FROM tb_asset t1 WHERE t1.del_flag = 0 AND t1.safety_score < 90.0)  AS unsafeAssetTotal\n  \n FROM tb_asset WHERE del_flag = 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:18:02','super','2023-07-27 17:31:45','100','1','100','','',1,NULL,0),('20230612112027160003','S-000605','[SZC安全运营中心] 告警概览_数量统计','table','sql','','SELECT\n        COUNT(1) AS allCount,\n        IFNULL(SUM(tar.order_status IN (\'归档\',\'无需处置\')), 0) AS doneCount,\n        IFNULL(SUM(tar.order_status NOT IN (\'归档\',\'无需处置\')), 0) AS undoneCount\nFROM\n        tb_alarm_report tar\nWHERE tar.del_flag = \'0\'\n  AND tar.create_time BETWEEN DATE_FORMAT(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\') \n                  AND DATE_FORMAT(\'${dateEnd<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:20:27','super','2023-06-20 16:54:30','100','1','100','','',1,NULL,0),('202306121120344450004','S-000606','[SZC安全运营中心] 告警概览_未完成高风险告警工单分页','table','sql','','SELECT\n        tar.id,\n        tar.business_key AS businessKey,\n        tar.alarm_id AS alarmId,\n        tar.title,\n        tar.attack_ip AS attackIp,\n        tar.victimized_ip AS victimizedIp,\n        tar.`level`,\n        tar.level_label AS levelLabel,\n        tar.attack_result AS attackResult,\n        tar.attack_result_label AS attackResultLabel,\n        tar.attack_means AS attackMeans,\n        tar.attack_means_label AS attackMeansLabel,\n        DATE_FORMAT(tar.create_time, \'%Y-%m-%d %H:%i:%S\') AS createTime,\n        tar.order_status AS orderStatus\nFROM\n        tb_alarm_report tar\nWHERE\n        tar.del_flag = \'0\'\n        AND tar.`level` IN (\'1\', \'2\')\n        AND tar.order_status IN (\'研判\', \'处置\', \'审核\')\n        AND tar.create_time BETWEEN DATE_FORMAT(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\') \n                  AND DATE_FORMAT(\'${dateEnd<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\nORDER BY tar.create_time DESC\nLIMIT ${pageStart<0>},  ${pageSize<20>}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup18','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:20:34','super','2023-06-19 16:15:11','100','1','100','','',1,NULL,0),('202306121120415310005','S-000607','[SZC安全运营中心] 告警概览_告警工单状态分布','table','sql','','SELECT\n        COUNT(tar.id) AS allCount,\n        t1.order_status AS orderStatus\nFROM\n        (\n        SELECT \'处置\' AS order_status\n        UNION ALL\n        SELECT \'研判\' AS order_status\n        UNION ALL\n        SELECT \'审核\' AS order_status\n        UNION ALL\n        SELECT \'归档\' AS order_status\n        UNION ALL\n        SELECT \'无需处置\' AS order_status\n        ) t1\nLEFT JOIN tb_alarm_report tar ON\n        tar.del_flag = \'0\'\n        AND t1.order_status = tar.order_status\n        AND tar.create_time BETWEEN DATE_FORMAT(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\') \n                  AND DATE_FORMAT(\'${dateEnd<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\nGROUP BY\n        t1.order_status',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\"35%\", \"50%\"],\"radius\":[\"60%\", \"70%\"],\"legendRight\":\"5%\",\"showNum\":5,\"legendDataColor\":{\"处置\":\"#02d2c6\",\"审核\":\"#8074ff\",\"归档\":\"#8cc115\",\"无需处置\":\"#bcc3d1\",\"研判\":\"#ffc836\"}}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:20:42','super','2023-06-20 16:59:47','100','1','100','','',1,NULL,0),('202306121121031730006','S-000608','[SZC安全运营中心] 集权系统被攻击情况_数量统计','table','sql','','SELECT\n        COUNT(1) AS allCount,\n        IFNULL(SUM(tar.order_status IN (\'归档\',\'无需处置\')), 0) AS doneCount,\n        IFNULL(SUM(tar.order_status NOT IN (\'归档\',\'无需处置\')), 0) AS undoneCount\nFROM\n        tb_alarm_report tar\nWHERE EXISTS (\n        SELECT\n                1\n        FROM\n                (\n                SELECT\n                        a.id,\n                        SUBSTRING_INDEX(SUBSTRING_INDEX(a.`victimized_ip`, \',\', b.help_topic_id), \',\',-1 ) AS ip\n                FROM\n                        tb_alarm_report a\n                LEFT JOIN mysql.help_topic b ON\n                        b.help_topic_id <= (LENGTH( a.`victimized_ip`) - LENGTH(REPLACE(a.`victimized_ip`, \',\', \'\')) + 1 )\n                WHERE\n                        a.del_flag = \'0\'\n                        AND a.create_time BETWEEN DATE_FORMAT(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\') \n                  AND DATE_FORMAT(\'${dateEnd<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')) t1\n        INNER JOIN (\n                SELECT\n                        ta.internal_ip\n                FROM\n                        tb_asset ta\n                WHERE\n                        ta.del_flag = \'0\'\n                        AND ta.centralized_system = \'1\') t2 ON\n                t1.ip = t2.internal_ip\n        WHERE\n                t1.id = tar.id\n)',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:21:03','super','2023-06-20 16:53:49','100','1','100','','',1,NULL,0),('202306121121145710007','S-000609','[SZC安全运营中心] 集权系统被攻击情况_工单列表','table','sql','','SELECT\n        tar.id,\n        tar.business_key AS businessKey,\n        tar.alarm_id AS alarmId,\n        tar.title,\n        tar.attack_ip AS attackIp,\n        tar.victimized_ip AS victimizedIp,\n        tar.`level`,\n        tar.level_label AS levelLabel,\n        tar.attack_result AS attackResult,\n        tar.attack_result_label AS attackResultLabel,\n        tar.attack_means AS attackMeans,\n        tar.attack_means_label AS attackMeansLabel,\n        DATE_FORMAT(tar.create_time, \'%Y-%m-%d %H:%i:%S\') AS createTime,\n        tar.order_status AS orderStatus\nFROM\n        tb_alarm_report tar\nWHERE EXISTS (\n        SELECT\n                1\n        FROM\n                (\n                SELECT\n                        a.id,\n                        SUBSTRING_INDEX(SUBSTRING_INDEX(a.`victimized_ip`, \',\', b.help_topic_id), \',\',-1 ) AS ip\n                FROM\n                        tb_alarm_report a\n                LEFT JOIN mysql.help_topic b ON\n                        b.help_topic_id <= (LENGTH( a.`victimized_ip`) - LENGTH(REPLACE(a.`victimized_ip`, \',\', \'\')) + 1 )\n                WHERE\n                        a.del_flag = \'0\'\n                        AND a.create_time BETWEEN DATE_FORMAT(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\') \n                  AND DATE_FORMAT(\'${dateEnd<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')) t1\n        INNER JOIN (\n                SELECT\n                        ta.internal_ip\n                FROM\n                        tb_asset ta\n                WHERE\n                        ta.del_flag = \'0\'\n                        AND ta.centralized_system = \'1\') t2 ON\n                t1.ip = t2.internal_ip\n        WHERE\n                t1.id = tar.id\n)\nORDER BY tar.create_time DESC\nLIMIT ${pageStart<0>},  ${pageSize<20>}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:21:15','super','2023-06-20 14:33:24','100','1','100','','',1,NULL,0),('202306121122011700008','S-000610','[SZC安全运营中心] 漏洞概览_数量统计','table','sql','','SELECT\n        \'all\' AS TYPE,\n        COUNT(*) AS total\nFROM\n        tb_vuln_process_form a\n        JOIN tb_vuln_process_handle_business b\n        ON a.code = b.vuln_code\n        WHERE a.del_flag = 0\n        AND b.`del_flag` = 0\n        AND is_push_status = 1\n        AND push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        UNION\n        ALL\n        SELECT\n        \'complete\' AS TYPE,\n        COUNT(*) AS total\n        FROM\n        (SELECT\n        COUNT(*)\n        FROM\n        tb_vuln_process_form a\n        LEFT JOIN tb_vuln_process_handle_business b\n        ON a.code = b.vuln_code\n        WHERE a.del_flag = 0\n        AND a.is_push_status = 1\n        AND a.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        AND b.del_flag = 0\n        AND b.work_order_state = 3\n        GROUP BY a.code) c\n        UNION\n        ALL\n        SELECT\n        \'noComplete\' AS TYPE,\n        COUNT(*) AS total\n        FROM\n        (SELECT\n        COUNT(*)\n        FROM\n        tb_vuln_process_form a\n        JOIN tb_vuln_process_handle_business b\n        ON a.code = b.vuln_code\n        WHERE a.del_flag = 0\n        AND a.is_push_status = 1\n        AND a.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        AND b.del_flag = 0\n        AND b.work_order_state != 3\n        GROUP BY a.code) c\n        UNION\n        ALL\n        SELECT\n        \'noCompleteHigh\' AS TYPE,\n        COUNT(*) AS total\n        FROM\n        (SELECT\n        COUNT(*)\n        FROM\n        tb_vuln_process_form a\n        JOIN tb_vuln_process_handle_business b\n        ON a.code = b.vuln_code\n        WHERE a.del_flag = 0\n        AND a.is_push_status = 1\n        AND a.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        AND (a.level IN (1, 2, 3)\n        OR a.category = 3)\n        AND b.del_flag = 0\n        AND b.work_order_state != 3\n        GROUP BY a.code) c\n        UNION\n        ALL\n        SELECT\n        \'noPush\' AS TYPE,\n        COUNT(*) AS total\n        FROM\n        tb_vuln_process_form\n        WHERE del_flag = 0\n        AND create_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        AND is_push_status = 0\n        UNION\n        ALL\n        SELECT\n        \'repair\' AS TYPE,\n        COUNT(*) AS total\n        FROM\n        (SELECT\n        COUNT(*)\n        FROM\n        tb_vuln_process_form a\n        LEFT JOIN tb_vuln_process_handle_record b\n        ON a.code = b.vuln_code\n        WHERE a.del_flag = 0\n        AND a.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        AND b.node_type in (\'approval\', \'review\')\n        AND b.action_type in( \'approvalPass\', \'reviewPass\')\n        AND a.`repair_time` < b.`deal_time`\n        GROUP BY a.code) c',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:22:01','super','2023-10-25 17:24:51','100','1','100','','',1,NULL,0),('202306121122139410009','S-000611','[SZC安全运营中心] 漏洞概览_未修复中高风险漏洞','table','sql','','SELECT DISTINCT tvlpf.id,\n        tvlpf.code,\n        CASE tvlpf.category WHEN \'3\' THEN (CONCAT(CONCAT_WS(\'/\' ,tvlpf.user_name, tvlpf.port, tvlpf.service), \' 存在弱口令\'))\n        ELSE tvlpf.vuln_name  END AS vuln_name,\n        tvlpf.ip,\n        IFNULL(tvlpf.vuln_type, \"\") AS vuln_type ,\n        tvlpf.cve_code,\nCASE tvlpf.category WHEN \'3\' THEN (CONCAT(CONCAT_WS(\'/\' ,tvlpf.user_name, tvlpf.port, tvlpf.service), \' 存在弱口令\'))\n        ELSE tvlpf.vuln_name  END AS description,\n        DATE_FORMAT(tvlpf.create_time, \'%Y-%m-%d %H:%i:%s\') AS create_time,\n        tvlphb.work_order_state,\n        CASE tvlphb.work_order_state WHEN \'1\' THEN \'待处置\' WHEN \'2\' THEN \'待审核\' WHEN \'3\' THEN \'已归档\' WHEN \'4\' THEN \'复查中\' \n        END AS work_order_state_label,\n        CASE tvlpf.category WHEN \'1\' THEN \'主机漏洞\' WHEN \'2\' THEN \'WEB漏洞\'  WHEN \'3\' THEN \'弱口令\'\n  END AS  categoryLabel,\n	category,\n        CASE tvlpf.category WHEN \'3\' THEN \'2\' ELSE tvlpf.level\n  END level,\n        CASE  WHEN tvlpf.category = \'3\' THEN \'高危\'\n        ELSE d.`dict_label`\n        END AS level_label\n        FROM tb_vuln_process_form tvlpf\n        JOIN tb_vuln_process_handle_business tvlphb ON tvlpf.code = tvlphb.vuln_code AND tvlphb.del_flag = \'0\'\n        LEFT JOIN sys_dict_data d ON d.dict_value = tvlpf.`level` AND dict_type = \'vul_level\'\n        WHERE tvlpf.del_flag = 0 AND  (tvlpf.level IN (1,2,3) OR tvlpf.category = 3) AND tvlphb.work_order_state != 3\n        AND tvlpf.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        ORDER BY tvlpf.create_time DESC  LIMIT  ${pageStart<0>},  ${pageSize<20>}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:22:14','super','2023-10-26 10:50:18','100','1','100','','',1,NULL,0),('202306121122206150010','S-000612','[SZC安全运营中心] 漏洞概览_漏洞等级分布','table','sql','','SELECT \n  SUM(a.total) AS total,\n  d.`dict_value` AS dictValue,\n  d.dict_label AS dictLabel \nFROM\n  (SELECT \n    CASE\n      WHEN a.`level` = \'0\' \n      THEN \'低危\' \n      WHEN a.`level` = \'1\' \n      THEN \'中危\' \n      WHEN a.`level` = \'2\' \n      THEN \'高危\' \n      WHEN a.`level` = \'3\' \n      THEN \'危急\' \n      WHEN a.`level` IS NULL \n      THEN \'高危\' \n    END AS TYPE,\n    IFNULL(b.total, 0) AS total \n  FROM\n    tb_vuln_process_form a \n    LEFT JOIN \n      (SELECT \n        a.type,\n        SUM(a.total) AS total\n      FROM\n        (SELECT \n          a.LEVEL AS TYPE,\n          COUNT(*) AS total \n        FROM\n          tb_vuln_process_form a \n          LEFT JOIN tb_vuln_process_handle_business b \n            ON a.code = b.`vuln_code` \n        WHERE a.del_flag = 0 \n          AND b.`del_flag` = 0 \n          AND a.category != 3 \n         AND a.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n        GROUP BY LEVEL \n        UNION\n        ALL \n        SELECT \n          \'2\' AS TYPE,\n          COUNT(*) AS total \n        FROM\n          tb_vuln_process_form a \n          LEFT JOIN tb_vuln_process_handle_business b \n            ON a.code = b.`vuln_code` \n        WHERE a.del_flag = 0 \n          AND b.`del_flag` = 0 \n          AND a.category = 3 \nAND a.push_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')          \n) a \n      GROUP BY a.type) b \n      ON a.`level` = b.TYPE \n  WHERE del_flag = 0 \n  GROUP BY LEVEL) a \n  LEFT JOIN sys_dict_data d \n    ON d.dict_label = a.type \n    AND dict_type = \'vul_level\' \nGROUP BY a.TYPE',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\"35%\", \"50%\"],\"radius\":[\"60%\", \"70%\"],\"legendRight\":\"5%\",\"showNum\":5,\"legendDataColor\":{\"危急\":\"#FF6347\",\"高危\":\"#FFA500\",\"中危\":\"#8074FF\",\"低危\":\"#267EE5\"}}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:22:21','super','2023-06-20 17:01:15','100','1','100','','',1,NULL,0),('202306121122315080011','S-000613','[SZC安全运营中心] 漏洞概览_漏洞工单状态分布','table','sql','','SELECT\n            d.`dict_value` AS dictValue,\n            IFNULL(b.total, 0) AS total,\n            d.`dict_label` AS dictLabel\n        FROM\n            tb_vuln_process_handle_business a\n            LEFT JOIN sys_dict_data d ON d.dict_value = a.work_order_state AND dict_type = \'vuln_work_status\'\n                LEFT JOIN\n            (SELECT\n                 b.`work_order_state` AS TYPE,\n                 COUNT(*) AS total\n             FROM\n                 tb_vuln_process_form a\n                     JOIN tb_vuln_process_handle_business b\n                          ON b.`vuln_code` = a.`code`\n             WHERE is_push_status = 1\n               AND a.del_flag = 0\n               AND b.`del_flag` = 0\n               \n                    AND a.push_time  BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n                \n             GROUP BY b.`work_order_state`) b\n            ON a.`work_order_state` = b.type\n        WHERE a.del_flag = 0\n        GROUP BY a.`work_order_state`\n        UNION\n            ALL\n        SELECT\n            \'0\' AS dictValue,\n            COUNT(*) AS total,\n            \"待推送\" AS  dictLabel\n        FROM\n            tb_vuln_process_form\n        WHERE is_push_status = 0\n          AND del_flag = 0\n             AND create_time BETWEEN STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            AND STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\"35%\", \"50%\"],\"radius\":[\"60%\", \"70%\"],\"legendRight\":\"5%\",\"showNum\":5,\"legendDataColor\":{\"待推送\":\"#BCC3D1\",\"待处置\":\"#FFA500\",\"待审核\":\"#8074FF\",\"复查中\":\"#267EE5\",\"已归档\":\"#19BE6B\"}}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:22:32','super','2023-06-20 17:01:32','100','1','100','','',1,NULL,0),('202306121122394890012','S-000614','[SZC安全运营中心] 告警流量趋势图','table','sql','','SELECT \n  DATE_FORMAT(a.dayStr,  \'${pattern<%Y-%m-%d>}\') AS type,\n  IFNULL(b.total, 0) AS total \nFROM\n  (SELECT \n    DATE_FORMAT(\n      DATE_ADD(\n        DATE_SUB(\n          (SELECT \n            DATE_SUB(${time<CURDATE()>} , INTERVAL  ${days<29>}  ${type<DAY>} )),\n          INTERVAL 1 ${type<DAY>}\n        ),\n        INTERVAL (CAST(help_topic_id AS SIGNED) + 1)  ${type<DAY>}\n    ),   \'${format<%Y-%m-%d>}\') AS  dayStr \n  FROM\n    mysql.help_topic \n  WHERE help_topic_id < ${days<29>} + 1\n  ORDER BY help_topic_id) a \n  LEFT JOIN \n    (\n    SELECT \n COUNT(a.total) AS total,\n a.type\n FROM (\nSELECT \n      COUNT(*) AS total,\n      DATE_FORMAT(create_time,   \'${format<%Y-%m-%d>}\') AS TYPE\n    FROM\n      tb_alarm_report \n    WHERE del_flag = 0 \n     and create_time between STR_TO_DATE(\'${dateStart<2023-05-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n            and STR_TO_DATE(\'${dateEnd<2023-06-01 00:00:00>}\', \'%Y-%m-%d %H:%i:%S\')\n    GROUP BY DATE_FORMAT(create_time, \'%Y-%m-%d %H:%i:%s\')\n) a GROUP BY a.type\n    ) b \n    ON a.dayStr = b.type \nORDER BY a.dayStr',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-12 11:22:39','super','2023-06-19 15:35:45','100','1','100','','',1,NULL,0),('202306131816034040004','S-000596','设备所属产品日志数量统计_1天','table','dsl','','{\n					\"aggs\": {\n						\"name\": {\n							\"terms\": {\n								\"field\": \"dev_ip.keyword\",\n								\"order\": {\n									\"_count\": \"desc\"\n								},\n								\"size\": 100\n							},\n							\"aggs\": {\n								\"child\": {\n									\"terms\": {\n										\"field\": \"product.keyword\",\n										\"order\": {\n											\"_count\": \"desc\"\n										},\n										\"missing\": \"__missing__\",\n										\"size\": 100\n									}\n								}\n							}\n						}\n					},\n					\"size\": 0,\n					\"query\": {\n						\"bool\": {\n							\"must\": [],\n							\"filter\": [{\n								\"range\": {\n									\"SparkTime\": {\n										 \"gte\": \"2023-06-06T00:00:00.104+0800\",\n										 \"lte\": \"2023-06-13T23:59:59.104+0800\",\n										\"format\": \"strict_date_optional_time\"\n									}\n								}\n							}],\n							\"should\": [],\n							\"must_not\": []\n						}\n					}\n				}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"设备IP\",\"field\":\"name\"},{\"name\":\"所属产品\",\"field\":\"child\"},{\"name\":\"近24小时日志量\",\"field\":\"count\"}]}','colorgroup16','','1','1','4','3',NULL,0,'sec_all*',NULL,NULL,'super','管理员','2023-06-13 18:16:03','super','2023-06-14 14:53:53','100','1','100','','',1,NULL,0),('202306151131479750001','S-000615','cessss','richText','sql','','',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'blue','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 11:31:48','super','2023-06-15 11:38:25','100','1','100','','',1,NULL,0),('202306151420115440004','S-000020','钓鱼邮件-全集团-发送数和送达数-新版','text-progress','sql','','SELECT IFNULL( total , 0 ) AS 发送数 , IFNULL( num_of_send , 0 ) AS 送达数 , \nIFNULL( num_of_send/total*100, 0 ) AS 送达率  \nFROM task_infos WHERE task_id = \"${taskId&lt;202111151&gt;}\" ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"发送数\",\"num\":1},{\"key\":\"送达数\",\"num\":2},{\"key\":\"送达率\",\"num\":3}]}','singleGreen','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:20:12','super','2023-06-15 14:20:39','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151424579590005','S-000021','钓鱼邮件-全集团-中招人数-新版','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS \'中招数\', \r\nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 )  AS \'中招率\' \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"中招数\",\"num\":1},{\"key\":\"中招率\",\"num\":2}]}','singleRed','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:24:58','super','2023-06-15 14:25:18','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151426022820003','S-000616','测试数据','richText','sql','','',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:26:02','super','2023-06-15 14:26:02','100','1','100','','',1,NULL,0),('202306151429398160006','S-000022','钓鱼邮件-全集团-打开附件人数-新版','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 打开附件人数 , \r\nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) AS 打开率 \r\nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 2 ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"打开附件人数\",\"num\":1},{\"key\":\"打开率\",\"num\":2}]}','singleYellow','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:29:40','super','2023-06-15 14:29:54','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151437531530007','S-000023','钓鱼邮件-全集团-点击邮件链接人数-新版','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 点击邮件链接人数 , \nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) AS 点击率 \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 1 ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"点击邮件链接人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:37:53','super','2023-06-15 15:23:37','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151448576820008','S-000023','钓鱼邮件-全集团-输入敏感信息人数-新版','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 输入敏感信息人数 , \nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) AS 点击率 \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 3',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"输入敏感信息人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:48:58','super','2023-06-15 14:51:04','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151449522370009','S-000023','钓鱼邮件-全集团-点击短信链接人数-新版','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 点击短信链接人数 , \nIFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) AS 点击率 \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 4',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"点击短信链接人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 14:49:52','super','2023-06-15 14:50:50','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151524096350010','S-000024','钓鱼邮件-全集团-各单位中招情况-新版','bar','sql','','(SELECT t.bu_name AS NAME , IFNULL(capCount, 0)/t.num_of_send * 100 AS COUNT, \'中招率\' AS CHILD\r\nFROM task_info t\r\n    LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \"${taskId&lt;202111151&gt;}\"  GROUP BY e.depend1 ) a ON a.task_id = t.task_id AND t.bu_name = a.depend1\r\n	  WHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_parent = \'\'\r\nORDER BY COUNT DESC\r\n)UNION(\r\nSELECT t.bu_name AS NAME , IFNULL(capCount, 0 ) AS COUNT, \'中招人数\' AS CHILD\r\nFROM task_info t\r\n    LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \"${taskId&lt;202111151&gt;}\"  GROUP BY e.depend1 ) a ON a.task_id = t.task_id AND t.bu_name = a.depend1\r\n	  WHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_parent = \'\'\r\nORDER BY COUNT DESC)',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{legendData:[\"中招人数\",\"中招率\"],\"yTwoAxisUnit\":\"%\",\"yTwoAxisLegend\":\"中招率\",\"labelPosition\":\"top\",\"labelFontSize\":11,\"legendDataColor\":{\"中招人数\":\"#71a3f3\",\"中招率\":\"#ffc836\"},\"barGap\":\"100%\",\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2}],\"dataOrder\":{\"field\":\"中招率\",\"sort\":\"desc\"}}','blueYellow','','','','','',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 15:24:10','super','2023-06-15 15:24:23','100','1','100',NULL,NULL,NULL,NULL,NULL),('2023061515314070011','S-000025','钓鱼邮件-全集团-中招高峰时间分布-新版','area','sql','','( SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'点击邮件链接人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 1 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'打开附件人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 2 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'输入敏感信息人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 3 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'点击短信链接人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND e.status = 4 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') )\nORDER BY NAME ASC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":[\"点击邮件链接人数\",\"打开附件人数\",\"输入敏感信息人数\",\"点击短信链接人数\"]}','colorgroup15','','3','3','3','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 15:31:40','super','2023-06-15 17:44:11','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151538259660012','S-000026','钓鱼邮件-全集团-中招率趋势-新版','line','sql','','SELECT cap_rate AS COUNT, cap_name AS NAME FROM (\r\nSELECT * FROM task_cap  WHERE cap_start &lt;= ( SELECT cap_start FROM task_cap WHERE task_id =  \"${taskId&lt;2021102201&gt;}\" AND bu_name = \"${buName&lt;华润集团（全集团）&gt;}\" )   \r\nAND bu_name = \"${buName&lt;华润集团（全集团）&gt;}\" AND task_type = ( SELECT task_type FROM task_cap WHERE task_id =  \"${taskId&lt;2021102201&gt;}\" AND bu_name = \"${buName&lt;华润集团（全集团）&gt;}\")\r\nORDER BY cap_start DESC LIMIT 0,5 ) AS t ORDER BY t.cap_start ASC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":\"中招率\",\"yAxisUnit\":\"%\",\"xaxisLabelRotate\":30}','singleBlue','','4','4','6','5',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 15:38:26','super','2023-06-15 15:39:02','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151544405050013','S-000027','钓鱼邮件-全集团-各单位中招数据-新版','table','sql','','( SELECT @rownum:=@rownum+1 AS \'排名\' , t.* FROM ( SELECT t.bu_name AS \'单位\' , IFNULL( t.total, 0 ) AS \'发送数\', \nIFNULL( t.num_of_send, 0 ) AS \'送达数\', IFNULL(capCount, 0 ) AS \'中招人数\',\nIFNULL(capCount, 0)/t.num_of_send * 100 AS \'中招率\', \nIFNULL(openCount, 0) AS \'打开邮件附件人数\', \nIFNULL(openCount, 0)/t.num_of_send * 100 AS \'邮件附件打开率\',  \nIFNULL(linkCount, 0) AS \'点击邮件链接人数\', \nIFNULL(linkCount, 0)/t.num_of_send * 100 AS \'邮件链接点击率\',\nIFNULL(qrCodeCount, 0) AS \'扫描二维码人数\', \nIFNULL(qrCodeCount, 0)/t.num_of_send * 100 AS \'二维码扫描率\',\nIFNULL(inputCount, 0) AS \'输入敏感信息人数\', \nIFNULL(inputCount, 0)/t.num_of_send * 100 AS \'敏感信息输入率\',\nIFNULL(noteCount, 0) AS \'点击短信链接人数\', \nIFNULL(noteCount, 0)/t.num_of_send * 100 AS \'短信链接点击率\'\nFROM task_info t\n    LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\"  GROUP BY e.depend1 ) a ON a.task_id = t.task_id AND t.bu_name = a.depend1\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS openCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 2 GROUP BY e.depend1 ) b\n	    ON a.depend1 = b.depend1\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS linkCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 1 GROUP BY e.depend1 ) c\n	    ON a.depend1 = c.depend1\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS qrCodeCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 5 GROUP BY e.depend1 ) g\n	    ON a.depend1 = g.depend1\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS inputCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 3 GROUP BY e.depend1 ) d\n	    ON a.depend1 = d.depend1\n	LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS noteCount, e.depend1 FROM target_emplorees e WHERE e.task_id = \"${taskId<202111151>}\" AND e.status = 4 GROUP BY e.depend1 ) f\n	    ON a.depend1 = f.depend1\n	  WHERE t.task_id = \"${taskId<202111151>}\" AND t.bu_parent = \'\'\nORDER BY 中招率 DESC ) t, (SELECT @rownum:=0) r ) \nUNION (\nSELECT \'总计\' AS \'排名\',  \'\' AS \'单位\',\n(SELECT IFNULL( total , 0 )  FROM task_infos WHERE task_id = \"${taskId<202111151>}\")  AS \'发送数\',\n(SELECT IFNULL( num_of_send , 0 )  FROM task_infos WHERE task_id = \"${taskId<202111151>}\")  AS \'送达数\',\n(SELECT COUNT( DISTINCT(e.email) ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\") AS \'中招人数\', \n( SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\") AS \'中招率\', \n(SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 2  ) AS \'打开邮件附件人数\', \n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 2 ) AS \'邮件附件打开率\' ,\n( SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 1 ) AS \'点击邮件链接人数\',\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 1) AS \'邮件链接点击率\',\n( SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 5 ) AS \'扫描二维码人数\',\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 5) AS \'二维码扫描率\',\n( SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 3 ) AS \'输入敏感信息人数\',\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 3) AS \'敏感信息输入率\',\n\n( SELECT COUNT( DISTINCT(e.email) ) FROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 4 ) AS \'点击短信链接人数\',\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 ) \nFROM target_emplorees e INNER JOIN task_infos t ON e.task_id = t.task_id\nWHERE t.task_id = \"${taskId<202111151>}\" AND e.status = 4) AS \'短信链接点击率\'\n\n)',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"排名\",\"field\":\"排名\"},{\"name\":\"单位\",\"field\":\"单位\"},{\"name\":\"发送数\",\"field\":\"发送数\"},{\"name\":\"送达数\",\"field\":\"送达数\"},{\"name\":\"中招人数\",\"field\":\"中招人数\"},{\"name\":\"中招率\",\"field\":\"中招率\"},{\"name\":\"打开邮件附件人数\",\"field\":\"打开邮件附件人数\"},{\"name\":\"邮件附件打开率\",\"field\":\"邮件附件打开率\"},{\"name\":\"点击邮件链接人数\",\"field\":\"点击邮件链接人数\"},{\"name\":\"邮件链接点击率\",\"field\":\"邮件链接点击率\"},{\"name\":\"扫描二维码人数\",\"field\":\"扫描二维码人数\"},{\"name\":\"二维码扫描率\",\"field\":\"二维码扫描率\"},{\"name\":\"输入敏感信息人数\",\"field\":\"输入敏感信息人数\"},{\"name\":\"敏感信息输入率\",\"field\":\"敏感信息输入率\"},{\"name\":\"点击短信链接人数\",\"field\":\"点击短信链接人数\"},{\"name\":\"短信链接点击率\",\"field\":\"短信链接点击率\"}],\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"邮件附件打开率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"邮件链接点击率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"二维码扫描率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"敏感信息输入率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"短信链接点击率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"}]}','blue','','4','4','4','4',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 15:44:41','super','2024-05-23 14:56:40','100','1','100',NULL,'',0,NULL,0),('202306151617118890014','S-000035','钓鱼邮件-全集团-中招详情-新版','table','sql','','  SELECT depend1 AS \'单位\', depend2 AS \'部门\', NAME AS \'姓名\', email AS \'邮箱\',  IF(MAX(isFile),\'是\',\'否\') AS \'是否打开邮件附件\' ,\r\n      IF(MAX(isLink),\'是\',\'否\') AS \'是否点击邮件链接\'  , IF(MAX(isInput),\'是\',\'否\') AS \'是否输入敏感信息\' ,\r\n      IF(MAX(isNote),\'是\',\'否\') AS \'是否点击短信链接\'  ,  min(cap_time) AS \'中招时间\'\r\n   FROM ( \r\n	SELECT depend1, depend2 , NAME, email ,IF(STATUS=2, 1, 0) AS isFile, IF(STATUS=1,1,IF(STATUS =3, 1, 0)) AS isLink ,IF(STATUS=3, 1, 0) AS isInput, IF(STATUS=4,1,0) AS isNote , cap_time\r\n	FROM target_emplorees WHERE task_id = \"${taskId&lt;202111151&gt;}\" ORDER BY cap_time DESC LIMIT 0,10000000 \r\n   ) a GROUP BY email ORDER BY MIN(cap_time) DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"单位\",\"field\":\"单位\"},{\"name\":\"部门\",\"field\":\"部门\"},{\"name\":\"姓名\",\"field\":\"姓名\"},{\"name\":\"邮箱\",\"field\":\"邮箱\"},{\"name\":\"是否打开邮件附件\",\"field\":\"是否打开邮件附件\"},{\"name\":\"是否点击邮件链接\",\"field\":\"是否点击邮件链接\"},{\"name\":\"是否输入敏感信息\",\"field\":\"是否输入敏感信息\"},{\"name\":\"是否点击短信链接\",\"field\":\"是否点击短信链接\"},{\"name\":\"中招时间\",\"field\":\"中招时间\"}]}','blue','','4','3','6','5',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 16:17:12','super','2023-06-15 16:49:00','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151703067180000','S-000028','发送数和送达数','text-progress','sql','','SELECT SUM(total) AS 发送数 , IFNULL( SUM(num_of_send), 0) AS 送达数 , IFNULL( SUM(num_of_send)/SUM(total)*100 , 0 ) AS 送达率  \nFROM task_info WHERE task_id = \"${taskId<202111151>}\"',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"发送数\",\"num\":1},{\"key\":\"送达数\",\"num\":2},{\"key\":\"送达率\",\"num\":3}]}','singleGreen','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:03:07','super','2024-06-06 17:31:33','100','1','100',NULL,'',0,NULL,0),('202306151708099430001','S-000029','中招人数','text-progress','sql','','SELECT \n    COUNT(DISTINCT (e.email)) AS \'中招数\',\n    IFNULL(\n      COUNT(DISTINCT (e.email)) / (\n        SELECT SUM(num_of_send) FROM task_info WHERE task_id = \"${taskId<202111151>}\"\n      ) * 100,\n      0\n    ) AS \'中招率\' \n  FROM\n    target_emplorees e \n  WHERE e.task_id = \"${taskId<202111151>}\"',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"中招数\",\"num\":1},{\"key\":\"中招率\",\"num\":2}]}','singleRed','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:08:10','super','2024-06-06 17:31:26','100','1','100',NULL,'',0,NULL,0),('202306151711104890002','S-000030','打开附件人数','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 打开附件人数 , IFNULL( COUNT( DISTINCT(e.email) ) / (SELECT \n        SUM(num_of_send) \n      FROM\n        task_info \n      WHERE task_id = \"${taskId<202111151>}\") * 100 , 0 ) AS 打开率 \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\" AND FIND_IN_SET(\'2\', e.status) > 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"打开附件人数\",\"num\":1},{\"key\":\"打开率\",\"num\":2}]}','singleYellow','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:11:10','super','2024-06-06 17:31:20','100','1','100',NULL,'',0,NULL,0),('202306151718365360003','S-000031','点击链接人数','text-progress','sql','','SELECT \n  COUNT(DISTINCT (e.email)) AS 点击邮件链接人数,\n  IFNULL(\n    COUNT(DISTINCT (e.email)) / \n    (SELECT \n      SUM(num_of_send) \n    FROM\n      task_info \n    WHERE task_id = \"${taskId<202111151>}\") * 100,\n    0\n  ) AS 点击率 \nFROM\n  target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\" \n  AND (FIND_IN_SET(\'1\', e.status) > 0 OR FIND_IN_SET(\'3\', e.status))',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"点击邮件链接人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:18:37','super','2024-06-06 17:31:13','100','1','100',NULL,'',0,NULL,0),('202306151734111520004','S-000031','输入敏感信息人数','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 输入敏感信息人数, IFNULL( COUNT( DISTINCT(e.email) ) / (SELECT \n        SUM(num_of_send) \n      FROM\n        task_info \n      WHERE task_id = \"${taskId<202111151>}\")  * 100, 0) AS 点击率 \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\" and FIND_IN_SET(\'3\', e.status) > 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"输入敏感信息人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:34:11','super','2024-06-06 17:31:05','100','1','100',NULL,'',0,NULL,0),('202306151734509600005','S-000031','点击短信链接人数','text-progress','sql','','SELECT COUNT( DISTINCT(e.email) ) AS 点击短信链接人数 , IFNULL( COUNT( DISTINCT(e.email) ) / (SELECT \n        SUM(num_of_send) \n      FROM\n        task_info \n      WHERE task_id = \"${taskId<202111151>}\") * 100, 0) AS 点击率 \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\"  AND FIND_IN_SET(\'4\', e.status) > 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"点击短信链接人数\",\"num\":1},{\"key\":\"点击率\",\"num\":2}]}','singleBlue','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:34:51','super','2024-06-06 17:30:56','100','1','100',NULL,'',0,NULL,0),('202306151742045170006','S-000033','中招高峰时间分布','area','sql','','( \nSELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'点击邮件链接人数\' AS child, DATE_FORMAT(cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\"  AND FIND_IN_SET(\'1\', e.status) > 0 GROUP BY DATE_FORMAT(cap_time, \'%H:00\') \n)\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'打开附件人数\' AS child, DATE_FORMAT(e.cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\"  AND FIND_IN_SET(\'2\', e.status) > 0 GROUP BY DATE_FORMAT(e.cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'输入敏感信息人数\' AS child, DATE_FORMAT(e.cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\"  AND FIND_IN_SET(\'3\', e.status) > 0 GROUP BY DATE_FORMAT(e.cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'扫描二维码人数\' AS child, DATE_FORMAT(e.cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\"  AND FIND_IN_SET(\'5\', e.status) > 0 GROUP BY DATE_FORMAT(e.cap_time, \'%H:00\') )\nUNION\n(   SELECT COUNT( DISTINCT(e.email) ) AS COUNT , \'点击短信链接人数\' AS child, DATE_FORMAT(e.cap_time, \'%H:00\') AS NAME \nFROM target_emplorees e \nWHERE e.task_id = \"${taskId<202111151>}\"  AND FIND_IN_SET(\'4\', e.status) > 0 GROUP BY DATE_FORMAT(e.cap_time, \'%H:00\') )\nORDER BY NAME ASC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":[\"点击邮件链接人数\",\"打开附件人数\",\"输入敏感信息人数\",\"扫描二维码人数\",\"点击短信链接人数\"]}','colorgroup15','','4','3','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:42:05','super','2024-06-06 17:30:49','100','1','100',NULL,'',0,NULL,0),('202306151746283910007','S-000034','中招率趋势','line','sql','','SELECT cap_rate AS COUNT,\n	cap_name AS NAME\nFROM\n	task_cap \n\ngroup by cap_name\nORDER BY\n	name \nLIMIT 0,\n5',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"legendData\":\"中招率\",\"yAxisUnit\":\"%\",\"xaxisLabelRotate\":30}','singleBlue','','','','','',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:46:28','super','2024-06-27 10:47:39','100','1','100',NULL,'',0,NULL,0),('202306151748282070008','S-000036','中招详情(按中招时间倒序排序)','table','sql','','SELECT depend1 AS \'单位\', depend2 AS \'部门\', NAME AS \'姓名\', email AS \'邮箱\',  IF(MAX(isFile),\'是\',\'否\') AS \'是否打开邮件附件\' ,\n      IF(MAX(isLink),\'是\',\'否\') AS \'是否点击邮件链接\'  , IF(MAX(isQRCode),\'是\',\'否\') AS \'是否扫描二维码\' , IF(MAX(isInput),\'是\',\'否\') AS \'是否输入敏感信息\' ,\n      IF(MAX(isNote),\'是\',\'否\') AS \'是否点击短信链接\'  ,  min(cap_time) AS \'中招时间\'\n   FROM ( \n	SELECT depend1, depend2 , NAME, email ,IF(STATUS=2, 1, 0) AS isFile, IF(STATUS=1,1,IF(STATUS =3, 1, 0)) AS isLink ,IF(STATUS=5, 1, 0) AS isQRCode,IF(STATUS=3, 1, 0) AS isInput, IF(STATUS=4,1,0) AS isNote , cap_time\n	FROM target_emplorees WHERE task_id = \"${taskId<202111151>}\" ORDER BY cap_time DESC LIMIT 0,10000000 \n   ) a GROUP BY email ORDER BY MIN(cap_time) DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"单位\",\"field\":\"单位\"},{\"name\":\"部门\",\"field\":\"部门\"},{\"name\":\"姓名\",\"field\":\"姓名\"},{\"name\":\"邮箱\",\"field\":\"邮箱\"},{\"name\":\"是否打开邮件附件\",\"field\":\"是否打开邮件附件\"},{\"name\":\"是否点击邮件链接\",\"field\":\"是否点击邮件链接\"},{\"name\":\"是否扫描二维码\",\"field\":\"是否扫描二维码\"},{\"name\":\"是否输入敏感信息\",\"field\":\"是否输入敏感信息\"},{\"name\":\"是否点击短信链接\",\"field\":\"是否点击短信链接\"},{\"name\":\"中招时间\",\"field\":\"中招时间\"}]}','blue','','4','3','6','5',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 17:48:28','super','2024-06-06 17:30:24','100','1','100',NULL,'',0,NULL,0),('202306151800452080009','S-000028','钓鱼邮件-重复-集团-BU单位-发送数和送达数-新版','text-progress','sql','','SELECT total AS 发送数 , IFNULL( num_of_send, 0) AS 送达数 , IFNULL( num_of_send/total*100 , 0 ) AS 送达率  \nFROM task_info WHERE task_id = \"${taskId<202111151>}\" AND bu_name = \"${buName<润联科技>}\"',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"dataHeader\":[{\"key\":\"发送数\",\"num\":1},{\"key\":\"送达数\",\"num\":2},{\"key\":\"送达率\",\"num\":3}]}','singleGreen','','1','1','1','1',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 18:00:45','super','2024-05-24 16:16:33','100','1','100',NULL,'',0,NULL,0),('202306151806126770010','S-000032','各单位中招情况(按中招率由高到低排序)','bar','sql','','( SELECT t.bu_name AS NAME , IFNULL(capCount, 0)/t.num_of_send * 100 AS COUNT,  \'中招率\' AS CHILD \n FROM task_info t\n   LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \'${taskId<202111151>}\'   GROUP BY e.depend1 ) a \n     on t.bu_name = a.depend1\n  where t.task_id = \"${taskId<202111151>}\" AND t.bu_parent = \'\' ORDER BY COUNT DESC \n) UNION (\n SELECT t.bu_name AS NAME , IFNULL(capCount, 0 ) AS COUNT, \'中招人数\' AS CHILD\n FROM task_info t\n   LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend1, e.task_id FROM target_emplorees e WHERE e.task_id = \'${taskId<202111151>}\'   GROUP BY e.depend1 ) a \n     on t.bu_name = a.depend1\n  where t.task_id = \"${taskId<202111151>}\" AND t.bu_parent = \'\' ORDER BY COUNT DESC\n  )',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{legendData:[\"中招人数\",\"中招率\"],\"yTwoAxisUnit\":\"%\",\"yTwoAxisLegend\":\"中招率\",\"labelPosition\":\"top\",\"labelFontSize\":11,\"legendDataColor\":{\"中招人数\":\"#71a3f3\",\"中招率\":\"#ffc836\"},\"barGap\":\"100%\",\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2}],\"dataOrder\":{\"field\":\"中招率\",\"sort\":\"desc\"}}','blueYellow','','4','3','6','5',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 18:06:13','super','2024-06-26 15:18:48','100','1','100',NULL,'',0,NULL,0),('202306151812183290011','S-000046','钓鱼邮件-全集团-BU单位-各部门中招数据-新版','table','sql','','(\r\nSELECT @rownum:=@rownum+1 AS \'排名\' , t.* FROM ( SELECT t.bu_name AS \'部门\' , IFNULL( t.total, 0 ) AS \'发送数\', \r\nIFNULL( t.num_of_send, 0 ) AS \'送达数\', IFNULL(capCount, 0 ) AS \'中招人数\', \r\nIFNULL(capCount, 0)/t.num_of_send * 100 AS \'中招率\', \r\nIFNULL(openCount, 0) AS \'打开邮件附件人数\', \r\nIFNULL(openCount, 0)/t.num_of_send * 100 AS \'邮件附件打开率\',\r\nIFNULL(linkCount, 0) AS \'点击邮件链接人数\',\r\nIFNULL(linkCount, 0)/t.num_of_send * 100 AS \'邮件链接点击率\',\r\n\r\nIFNULL(inputCount, 0) AS \'输入敏感信息人数\', \r\nIFNULL(inputCount, 0)/t.num_of_send * 100 AS \'敏感信息输入率\',\r\nIFNULL(noteCount, 0) AS \'点击短信链接人数\', \r\nIFNULL(noteCount, 0)/t.num_of_send * 100 AS \'短信链接点击率\'\r\n\r\n FROM \r\ntask_info t\r\n LEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS capCount, e.depend2, e.task_id FROM target_emplorees e WHERE e.task_id = \'${taskId&lt;202111151&gt;}\' AND e.depend1=\"${buName&lt;润联科技&gt;}\"  GROUP BY e.depend2 ) a \r\n  on t.bu_name = a.depend2\r\nLEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS openCount, e.depend2 FROM target_emplorees e WHERE e.task_id = \'${taskId&lt;202111151&gt;}\'  AND e.depend1=\"${buName&lt;润联科技&gt;}\" AND e.status = 2 GROUP BY e.depend2 ) b \r\n  ON t.bu_name = b.depend2 \r\nLEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS linkCount, e.depend2 FROM target_emplorees e WHERE e.task_id = \'${taskId&lt;202111151&gt;}\' AND e.depend1=\"${buName&lt;润联科技&gt;}\" AND e.status = 1 GROUP BY e.depend2 ) c \r\n  ON t.bu_name = c.depend2 \r\n  \r\nLEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS inputCount, e.depend2 FROM target_emplorees e WHERE e.task_id = \'${taskId&lt;202111151&gt;}\'  AND e.depend1=\"${buName&lt;润联科技&gt;}\" AND e.status = 3 GROUP BY e.depend2 ) d \r\n  ON t.bu_name = d.depend2 \r\nLEFT JOIN ( SELECT COUNT( DISTINCT(e.email) ) AS noteCount, e.depend2 FROM target_emplorees e WHERE e.task_id = \'${taskId&lt;202111151&gt;}\' AND e.depend1=\"${buName&lt;润联科技&gt;}\" AND e.status = 4 GROUP BY e.depend2 ) f \r\n  ON t.bu_name = f.depend2 \r\n  \r\n  where t.task_id = \"${taskId&lt;202111151&gt;}\" and t.bu_parent =\'${buName&lt;润联科技&gt;}\'  ORDER BY 中招率 DESC ) t, (SELECT @rownum:=0) r \r\n)\r\nUNION\r\n(\r\nSELECT \'总计\' AS \'排名\',  \'\' AS \'单位\',\r\n(SELECT total  FROM task_info WHERE task_id = \"${taskId&lt;202111151&gt;}\" AND bu_name = \"${buName&lt;润联科技&gt;}\" ) AS \'发送数\',\r\n(SELECT IFNULL( num_of_send, 0)  FROM task_info WHERE task_id = \"${taskId&lt;202111151&gt;}\" AND bu_name = \"${buName&lt;润联科技&gt;}\" ) AS \'发送数\',\r\n(SELECT COUNT( DISTINCT(e.email) )  \r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\") AS  \'中招人数\',\r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0)  \r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\") AS \'中招率\',\r\n( SELECT COUNT( DISTINCT(e.email) ) \r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 2  ) AS \'打开邮件附件人数\', \r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 )\r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 2 ) AS \'邮件附件打开率\',\r\n(SELECT COUNT( DISTINCT(e.email) ) \r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 1) AS \'点击邮件链接人数\',\r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 )\r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 1) AS \'邮件链接点击率\',\r\n\r\n(SELECT COUNT( DISTINCT(e.email) ) \r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 3) AS \'输入敏感信息人数\',\r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 )\r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 3) AS \'敏感信息输入率\',\r\n\r\n(SELECT COUNT( DISTINCT(e.email) ) \r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 4) AS \'点击短信链接人数\',\r\n(SELECT IFNULL( COUNT( DISTINCT(e.email) ) / t.num_of_send * 100 , 0 )\r\nFROM target_emplorees e INNER JOIN task_info t ON e.task_id = t.task_id AND e.depend1 = t.bu_name\r\nWHERE t.task_id = \"${taskId&lt;202111151&gt;}\" AND t.bu_name = \"${buName&lt;润联科技&gt;}\" AND e.status = 4) AS \'短信链接点击率\',\r\n)\r\n\r\n',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"排名\",\"field\":\"排名\"},{\"name\":\"部门\",\"field\":\"部门\"},{\"name\":\"发送数\",\"field\":\"发送数\"},{\"name\":\"送达数\",\"field\":\"送达数\"},{\"name\":\"中招人数\",\"field\":\"中招人数\"},{\"name\":\"中招率\",\"field\":\"中招率\"},{\"name\":\"打开邮件附件人数\",\"field\":\"打开邮件附件人数\"},{\"name\":\"邮件附件打开率\",\"field\":\"邮件附件打开率\"},{\"name\":\"点击邮件链接人数\",\"field\":\"点击邮件链接人数\"},{\"name\":\"邮件链接点击率\",\"field\":\"邮件链接点击率\"},{\"name\":\"输入敏感信息人数\",\"field\":\"输入敏感信息人数\"},{\"name\":\"敏感信息输入率\",\"field\":\"敏感信息输入率\"},{\"name\":\"点击短信链接人数\",\"field\":\"点击短信链接人数\"},{\"name\":\"短信链接点击率\",\"field\":\"短信链接点击率\"}],\"dataFormat\":[{\"field\":\"中招率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"邮件附件打开率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"邮件链接点击率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"敏感信息输入率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"},{\"field\":\"短信链接点击率\",\"type\":\"decimal\",\"point\":2,\"unit\":\"%\"}]}\n','blue','','4','4','4','4',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 18:12:18','super','2023-06-15 18:23:33','100','1','100',NULL,NULL,NULL,NULL,NULL),('202306151836199960013','S-000037','钓鱼邮件-BU单位-中招详情-新版','table','sql','','SELECT depend2 AS \'部门\', NAME AS \'姓名\', email AS \'邮箱\',  IF(MAX(isFile),\'是\',\'否\') AS \'是否打开邮件附件\' ,\n      IF(MAX(isLink),\'是\',\'否\') AS \'是否点击邮件链接\'  , IF(MAX(isQRCode),\'是\',\'否\') AS \'是否扫描二维码\' , IF(MAX(isInput),\'是\',\'否\') AS \'是否输入敏感信息\' ,\n      IF(MAX(isNote),\'是\',\'否\') AS \'是否点击短信链接\'  , min(cap_time) AS \'中招时间\'\n   FROM ( \n	SELECT depend2 , NAME, email ,IF(STATUS=2, 1, 0) AS isFile, IF(STATUS=1,1,IF(STATUS =3, 1, 0)) AS isLink ,IF(STATUS=5, 1, 0) AS isQRCode,IF(STATUS=3, 1, 0) AS isInput, IF(STATUS=4,1,0) AS isNote , cap_time\n	FROM target_emplorees WHERE task_id = \"${taskId<202111151>}\" AND depend1=\"${buName<润联科技>}\" ORDER BY cap_time DESC LIMIT 0,10000000 \n   ) a GROUP BY email ORDER BY MIN(cap_time) DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"部门\",\"field\":\"部门\"},{\"name\":\"姓名\",\"field\":\"姓名\"},{\"name\":\"邮箱\",\"field\":\"邮箱\"},{\"name\":\"是否打开邮件附件\",\"field\":\"是否打开邮件附件\"},{\"name\":\"是否点击邮件链接\",\"field\":\"是否点击邮件链接\"},{\"name\":\"是否扫描二维码\",\"field\":\"是否扫描二维码\"},{\"name\":\"是否输入敏感信息\",\"field\":\"是否输入敏感信息\"},{\"name\":\"是否点击短信链接\",\"field\":\"是否点击短信链接\"},{\"name\":\"中招时间\",\"field\":\"中招时间\"}]}','blue','','4','3','6','5',NULL,0,'',NULL,NULL,'super','管理员','2023-06-15 18:36:2