583480033','S-000645','全部告警工单_副本_副本','table','sql','','SELECT \nalarm_id AS \'告警ID\', \ntitle AS \'告警标题\',\nattack_ip AS \'攻击IP\', \nvictimized_ip AS \'受害IP/URL\',\nlevel_label AS \'告警级别\',\nattack_result_label AS \'攻击结果\',\nattack_means_label AS \'攻击手段\',\norder_status AS \'工单状态\',\nDATE_FORMAT(alarm_time, \'%Y-%m-%d %H:%m:%s\') AS \'告警时间\'\nFROM tb_alarm_report \nWHERE del_flag = \'0\' \nAND DATE_FORMAT(alarm_time, \'%Y-%m-%d\') BETWEEN dateStart AND dateEnd\nORDER BY alarm_time DESC',NULL,'{\"timeType\":\"1\",\"dateStart\":\"2023-06-08 13:52:20\",\"dateEnd\":\"2023-09-06 13:52:20\",\"recentlyTime\":\"\"}','{\"tableHeader\":[\n{\"name\":\"告警ID\",\"field\":\"告警ID\",\"width\":\"140\"},\n{\"name\":\"告警标题\",\"field\":\"告警标题\",\"minWidth\":\"200\"},\n{\"name\":\"攻击IP\",\"field\":\"攻击IP\",\"width\":\"130\"},\n{\"name\":\"受害IP/URL\",\"field\":\"受害IP/URL\",\"width\":\"130\"},\n{\"name\":\"告警级别\",\"field\":\"告警级别\",\"width\":\"90\"},\n{\"name\":\"攻击结果\",\"field\":\"攻击结果\",\"width\":\"90\"},\n{\"name\":\"攻击手段\",\"field\":\"攻击手段\",\"width\":\"200\"},\n{\"name\":\"工单状态\",\"field\":\"工单状态\",\"width\":\"90\"},\n{\"name\":\"告警时间\",\"field\":\"告警时间\",\"width\":\"160\"}],\"pagination\":\"true\",\"pagerCount\":7,\"pageSize\":20}','colorgroup17','','1','1','4','3',NULL,0,'',NULL,NULL,'liudongmei','刘冬梅01','2023-11-28 15:15:58','liudongmei','2023-11-28 15:15:58','100','1','100','','',1,NULL,0),('20231128151720890039','S-000302','[智慧安全协同平台｜首页] 安全告警总数_副本1','count','sql','','select FORMAT(count(*) , 0 ) as count from tb_alarm_report',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"安全告警总数\"}','blue',NULL,'','','','','/profile/upload/2022/01/11/202201111530418870002.png',0,'',NULL,NULL,'liudongmei','刘冬梅01','2023-11-28 15:17:20','liudongmei','2023-11-28 15:17:20','100','1','100',NULL,NULL,0,NULL,0),('202311301859005360001','S-000677','[集团安全运营中心] 累计攻击监测','table','sql','','请输入...',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,'','super','管理员','2023-11-30 18:59:01','super','2023-11-30 19:01:24','100','1','100','','',1,NULL,0),('202311301901596760002','S-000677','[集团安全运营中心] 资产管理-资产总数','table','sql','','SELECT SUM(num) AS total FROM (         \n SELECT COUNT(*) num FROM tb_asset WHERE del_flag = 0\n   UNION ALL \n SELECT COUNT(*) FROM tb_asset_terminal_equipment WHERE del_flag = \'0\'\n) t',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,'','super','管理员','2023-11-30 19:02:00','super','2023-12-04 16:05:02','100','1','100','','',1,NULL,0),('202312041048495700009','S-000678','[集团安全运营中心]脆弱性管理','table','sql','','SELECT\n    COUNT(1) AS vulnCount,\n    IFNULL(SUM(tvpf.category IN (\'1\', \'3\')), 0) AS hostCount,\n    IFNULL(SUM(tvpf.category = \'2\'), 0) AS webCount,\n    IFNULL(SUM(tvpf.category IN (\'1\', \'2\') AND tvpf.`level` = \'3\'), 0) AS criticalCount,\n    IFNULL(SUM(tvpf.category IN (\'1\', \'2\') AND tvpf.`level` = \'2\'), 0) + IFNULL(SUM(tvpf.category = \'3\'), 0) AS highCount,\n    IFNULL(SUM(tvpf.category IN (\'1\', \'2\') AND tvpf.`level` = \'1\'), 0) AS mediumCount,\n    IFNULL(SUM(tvpf.category IN (\'1\', \'2\') AND tvpf.`level` = \'0\'), 0) AS lowCount\nFROM\n    tb_vuln_process_form tvpf\nWHERE\n    tvpf.del_flag = \'0\'',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 10:48:50','super','2023-12-21 15:55:36','100','1','100','','',1,NULL,0),('20231204113242480016','S-000600','jxq-test','line','dsl','','{\n    \"from\": 0,\n    \"size\": 5,\n    \"query\": {\n        \"bool\": {\n            \"filter\": [\n                {\n                    \"bool\": {\n                        \"filter\": [\n                            {\n                                \"range\": {\n                                    \"SparkTime\": {\n                                        \"from\": \"2023-12-04T01:47:39.000+0000\",\n                                        \"to\": \"2023-12-04T02:47:39.000+0000\",\n                                        \"include_lower\": false,\n                                        \"include_upper\": true,\n                                        \"boost\": 1.0\n                                    }\n                                }\n                            }\n                        ],\n                        \"adjust_pure_negative\": true,\n                        \"boost\": 1.0\n                    }\n                }\n            ],\n            \"adjust_pure_negative\": true,\n            \"boost\": 1.0\n        }\n    },\n    \"sort\": [\n        {\n            \"SparkTime\": {\n                \"order\": \"desc\"\n            }\n        }\n    ],\n    \"track_total_hits\": 2147483647\n}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'sec_all*',NULL,NULL,'super','管理员','2023-12-04 11:32:42','super','2023-12-04 11:32:42','100','1','100','','',1,NULL,0),('202312041148264320027','S-000679','[集团安全运营中心]威胁处置','table','sql','','SELECT\n	COUNT(1) AS alarmCount,\n	IFNULL(SUM(tar.order_status IN (\'归档\', \'无需处置\')), 0) AS alarmLoopCount\nFROM\n	tb_alarm_report tar\nWHERE\n	tar.del_flag = \'0\'',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 11:48:26','super','2023-12-04 11:49:02','100','1','100','','',1,NULL,0),('202312041352281410121','S-000680','[集团安全运营中心]威胁处置类型top5','table','sql','','SELECT\n	COUNT(1) AS alarmTypeCount,\n	IFNULL(sdd.remark, tar.attack_means) AS alarmTypeLabel\nFROM\n	tb_alarm_report tar\nLEFT JOIN sys_dict_data sdd ON sdd.dict_type = \'attack_type\' AND tar.attack_means = sdd.dict_value\nWHERE\n	tar.del_flag = \'0\'\n	AND tar.order_status IN (\'归档\', \'无需处置\')\nGROUP BY\n	alarmTypeLabel\nORDER BY\n	alarmTypeCount DESC\nLIMIT 5',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 13:52:28','super','2023-12-07 11:16:50','100','1','100','','',1,NULL,0),('202312041434508800000','S-000681','[集团安全运营中心]脆弱性处置','table','sql','','SELECT\n	COUNT(1) AS vulnCount,\n	IFNULL(SUM(tvphb.work_order_state = \'3\') , 0) AS vulnLoopCount\nFROM\n	tb_vuln_process_form tvpf\nLEFT JOIN tb_vuln_process_handle_business tvphb ON\n	tvphb.del_flag = \'0\'\n	AND tvpf.code = tvphb.vuln_code\nWHERE\n	tvpf.del_flag = \'0\'\n	AND (tvpf.category = \'3\' OR (tvpf.category IN (\'1\', \'2\') AND tvpf.`level` IN (\'1\', \'2\', \'3\')))',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 14:34:51','super','2023-12-04 14:34:51','100','1','100','','',1,NULL,0),('20231204144016510001','S-000682','[集团安全运营中心]脆弱性处置类型','table','sql','','SELECT\n	COUNT(1) AS vulnTypeCount,\n	tvpf.vuln_type AS vulnTypeLabel\nFROM\n	tb_vuln_process_form tvpf\nLEFT JOIN tb_vuln_process_handle_business tvphb ON\n	tvphb.del_flag = \'0\'\n	AND tvpf.code = tvphb.vuln_code\nWHERE\n	tvpf.del_flag = \'0\'\n	AND tvpf.category IN (\'1\', \'2\')\n        AND tvpf.`level` IN (\'1\', \'2\', \'3\')\n	AND tvphb.work_order_state = \'3\'\nGROUP BY\n	vulnTypeLabel\nORDER BY\n	vulnTypeCount DESC\nLIMIT 5',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 14:40:16','super','2023-12-13 18:19:14','100','1','100','','',1,NULL,0),('202312041614556760000','S-000683','[集团安全运营中心] 资产管理-网络安全资产/信息化资产/哑终端资产','table','sql','','SELECT \nSUM(FIND_IN_SET(2, asset_type_path ) > 0) AS secuProTotal,\nSUM(FIND_IN_SET(101, asset_type_path ) > 0) AS  serverTotal,\nSUM(FIND_IN_SET(3, asset_type_path ) > 0) AS  internetOfThingsTotal\nFROM tb_asset  WHERE del_flag = \'0\' AND asset_type_id IS NOT NULL;',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 16:14:56','super','2023-12-20 14:16:52','100','1','100','','',1,NULL,0),('202312041620477810002','S-000685','[集团安全运营中心] 资产管理-终端资产','table','sql','','SELECT COUNT(*)  AS total  FROM tb_asset_terminal_equipment WHERE del_flag = \'0\'',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-04 16:20:48','super','2023-12-04 16:28:17','100','1','100','','',1,NULL,0),('202312050959122920010','S-000687','[集团安全运营中心]威胁处置工单','count','sql','','SELECT COUNT(*)  AS num  FROM tb_alarm_report\nWHERE create_time >= CURDATE() AND alarm_time < CURDATE() + INTERVAL 1 DAY;',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-05 09:59:12','super','2023-12-14 14:43:11','100','1','100','','',1,NULL,0),('202312051011555830011','S-000688','[集团安全运营中心]漏洞类型','text-progress','sql','','SELECT\n	tvlpf.vuln_type AS  label\nFROM tb_vuln_process_form tvlpf\n        INNER JOIN tb_vuln_process_handle_business tvlphb ON tvlpf.code = tvlphb.vuln_code AND tvlphb.del_flag = \'0\'\n         LEFT JOIN tb_asset ta ON tvlpf.ip = ta.internal_ip AND ta.del_flag = \'0\'\n         WHERE tvlpf.category IN (1,2)\n         GROUP BY tvlpf.vuln_type',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-05 10:11:56','jiashuai','2023-12-07 16:25:39','100','1','100','','',1,NULL,0),('202312051409075270040','S-000689','[集团安全运营中心]告警类型','line','sql','','SELECT \n b.remark AS   label,\n a.`attack_means`   AS   attackMeans\nFROM\n  tb_alarm_report a \n  LEFT JOIN sys_dict_data b ON b.`dict_label` = a.`attack_means` AND b.dict_type = \'attack_type\'\n  GROUP BY a.`attack_means`',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-05 14:09:08','jiashuai','2023-12-07 16:25:29','100','1','100','','',1,NULL,0),('202312051421146070041','S-000601','[集团安全运营中心]安全分析原始数据','count','dsl','','{\n  \"query\": {\n    \"bool\": {\n      \"filter\": [\n        {\n          \"bool\": {\n            \"filter\": [\n              {\n                \"range\": {\n                  \"SparkTime\": {\n                    \"from\": \'${startTime<2023-12-06T00:00:00.000+0000>}\',\n                    \"to\": \"now\",\n                    \"include_lower\": false,\n                    \"include_upper\": true,\n                    \"boost\": 1\n                  }\n                }\n              }\n            ],\n            \"adjust_pure_negative\": true,\n            \"boost\": 1\n          }\n        }\n      ],\n      \"adjust_pure_negative\": true,\n      \"boost\": 1\n    }\n  }\n}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'sec_all*,alarm_all*,user_all*',NULL,NULL,'super','管理员','2023-12-05 14:21:15','super','2023-12-11 15:54:31','100','1','100','','',1,NULL,0),('202312060951244530000','S-000572','[集团安全运营中心] 安全防护','pie','static','','[ { \"name\": \"防护\", \"child\": [ \"防火墙\", \"主机安全\", \"抗DDOS\", \"应用防火墙应用\", \"入侵防护\", \"防病毒\" ] }, { \"name\": \"监测\", \"child\": [ \"流量监测\", \"漏洞扫描\", \"入侵检测\", \"蜜罐\" ] }, { \"name\": \"审计\", \"child\": [ \"上网行为管理\", \"日志审计\", \"堡垒机\", \"数据库审计\" ] } ]',NULL,'\"{\\\"timeType\\\":\\\"0\\\",\\\"dateStart\\\":\\\"\\\",\\\"dateEnd\\\":\\\"\\\",\\\"recentlyTime\\\":\\\"\\\"}\"',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-06 09:51:24','super','2023-12-15 10:21:55','100','1','100','','',1,NULL,0),('202312061409325540000','S-000690','[集团安全运营中心]实时威胁告警','table','sql','','SELECT\n        t.id,\n        t.alarm_id AS alarmId,\n        t.attack_ip AS attackIp,\n        IFNULL(GROUP_CONCAT(ta.`instance`), t.victimized_ip) AS victimizedAsset,\n        DATE_FORMAT(t.alarm_time, \'%Y-%m-%d %H:%m:%s\') AS alarmTime,\n        IFNULL(sdd.remark, t.attack_means) AS alarmTypeLabel,\n        t.`level`,\n        t.level_label AS levelLabel,\n        t.business_key AS businessKey\nFROM (\n        SELECT tar.id,\n               tar.alarm_id,\n               tar.attack_ip,\n               tar.victimized_ip,\n               tar.alarm_time,\n               tar.attack_means,\n               tar.`level`,\n               tar.level_label,\n               tar.`business_key`\n        FROM tb_alarm_report tar\n        WHERE tar.del_flag = \'0\'\n          AND tar.create_time >= DATE_SUB(NOW(), INTERVAL 24 HOUR)\n        ) t\nLEFT JOIN sys_dict_data sdd ON sdd.dict_type = \'attack_type\' AND t.attack_means = sdd.dict_value\nLEFT JOIN tb_asset_alarm taa ON taa.`type` IN (\'2\', \'3\') AND t.id = taa.alarm_id\nLEFT JOIN tb_asset ta ON ta.del_flag = \'0\' AND taa.asset_id = ta.id\nGROUP BY t.id\nORDER BY t.alarm_time DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-06 14:09:33','super','2024-01-23 17:43:45','100','1','100','','',1,NULL,0),('202312061432578890000','S-000691','[集团安全运营中心] 蓝色箭头上方数据','table','sql','','SELECT sys_zh_name as label FROM tb_asset_app_system WHERE del_flag = \'0\' GROUP BY sys_zh_name',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-06 14:32:58','super','2023-12-08 10:15:26','100','1','100','','',1,NULL,0),('202312061433238750001','S-000692','[集团安全运营中心] 蓝色箭头下方数据','table','sql','','SELECT data_source_device as label FROM tb_database_device WHERE del_flag = \'0\' group by data_source_device',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-06 14:33:24','super','2023-12-08 10:14:04','100','1','100','','',1,NULL,0),('202312071035032310000','S-000693','[集团安全运营中心] 安全平稳运行天数','table','sql','','SELECT DATEDIFF(CURDATE(), \'2020-12-01\') AS daysDiff',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-07 10:35:03','super','2023-12-12 11:36:53','100','1','100','','',1,NULL,0),('202312081424013930000','S-000694','[集团安全运营中心]主机防护覆盖率','table','sql','','SELECT \n    COUNT(1) AS assetCount,\n    (COUNT(DISTINCT tqa.ip)) AS protectionCount  \nFROM tb_asset ta\nLEFT JOIN tb_qingteng_agent tqa ON ta.internal_ip = tqa.ip\nWHERE ta.del_flag = \'0\'\n  AND FIND_IN_SET(8, ta.asset_type_path) > 0\n  AND FIND_IN_SET(\'628\', ta.dept_path) > 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-08 14:24:01','super','2024-11-25 17:19:12','100','1','100','','',1,NULL,0),('202312081445588600001','S-000602','[集团安全运营中心]累计监测攻击','count','dsl','','{\n  \"track_total_hits\": true, \n  \"query\": {\n    \"bool\": {\n      \"must\": [\n        {\n          \"terms\": {\n            \"log_level.keyword\": [\"高风险\", \"中风险\"]\n          }\n        },\n        {\n          \"terms\": {\n            \"product.keyword\": [\"亚信防病毒\", \"青藤HIDS\", \"长亭WAF\", \"深信服SIP\", \"启明星辰SIP\", \"安恒APT\"]\n          }\n        }\n      ]\n    }\n  }\n}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'sec_all*',NULL,NULL,'super','管理员','2023-12-08 14:45:59','super','2023-12-11 16:28:53','100','1','100','','',1,NULL,0),('202312081451367260002','S-000695','[集团安全运营中心]系统整体安全评分','table','sql','','SELECT score,\nCASE \nWHEN score >=90 AND score <= 100 THEN \'优秀\'\nWHEN score >=80 AND score < 90 THEN \'良好\'\nWHEN score >=70 AND score < 80 THEN \'一般\'\nELSE \'较差\'\nEND AS `level` FROM (\n\nSELECT \nROUND(SUM(avraScore)/COUNT(*)) AS score\nFROM (\nSELECT SUM(ta.safety_score)/COUNT(*) AS avraScore FROM tb_asset_app_system taas INNER JOIN tb_app_system_relation_asset tasra ON taas.id = tasra.app_system_id LEFT JOIN tb_asset ta ON tasra.asset_id = ta.id \nWHERE  taas.del_flag = 0 AND tasra.del_flag = \'0\' \nGROUP BY tasra.app_system_id\n) t )tt',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-08 14:51:37','super','2023-12-15 10:20:42','100','1','100','','',1,NULL,0),('202312081452225110003','S-000603','[集团安全运营中心]累计封堵攻击','count','dsl','','{\n  \"track_total_hits\": true, \n  \"query\": {\n    \"bool\": {\n      \"must\": [\n        {\n          \"terms\": {\n            \"log_level.keyword\": [\"高风险\", \"中风险\"]\n          }\n        },\n        {\n          \"terms\": {\n            \"product.keyword\": [\"亚信防病毒\", \"青藤HIDS\", \"长亭WAF\", \"深信服SIP\", \"启明星辰SIP\", \"安恒APT\"]\n          }\n        },\n        {\n          \"terms\": {\n            \"action_result.keyword\": [\"拦截\", \"失败\"]\n          }\n        }\n      ]\n    }\n  }\n}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'sec_all*',NULL,NULL,'super','管理员','2023-12-08 14:52:23','super','2023-12-11 16:31:41','100','1','100','','',1,NULL,0),('202312081455364200004','S-000696','[集团安全运营中心]资产信息完整率','table','sql','','SELECT\n  100 - ROUND(IFNULL(\n    CASE\n      WHEN ( tt.keyInfoIncompleteAssetNumber / tt.ipAssetNumber * 10000 ) < 1\n      THEN CEILING(tt. keyInfoIncompleteAssetNumber / tt. ipAssetNumber * 10000) / 100\n      ELSE FLOOR(tt. keyInfoIncompleteAssetNumber / tt. ipAssetNumber * 10000) / 100\n    END, 0)) AS assetInfoIntegrityRate\nFROM\n  (SELECT\n    COUNT(DISTINCT t1.`id`) AS ipAssetNumber,\n    IFNULL(SUM(\n      ISNULL(t1.`affiliation_dept_name`)\n      OR t1.`affiliation_dept_name` = \'\'\n      OR ISNULL(t1.`affiliation_dept_node_id`)\n      OR t1.`affiliation_dept_node_id` = \'\'\n      OR ISNULL(tapu.`asset_id`)\n    ), 0) AS keyInfoIncompleteAssetNumber\n  FROM\n    tb_asset t1\n    \n    LEFT JOIN \n	(SELECT tap.* FROM tb_asset_person tap LEFT JOIN v_user u ON tap.user_id =  u.user_id \n	WHERE   tap.`type` = \'1\'\n        AND u.del_flag = \'0\'\n        AND u.status = \'0\') tapu ON t1.`id` = tapu.`asset_id`\n  WHERE t1.`del_flag` = \'0\') tt',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-08 14:55:36','super','2023-12-08 15:13:24','100','1','100','','',1,NULL,0),('202312081523528910005','S-000604','[集团安全运营中心]24小时攻击趋势','area','dsl','','{  \n  \"size\": 0, \n  \"query\": {  \n    \"bool\": {  \n      \"must_not\": [  \n        {  \n          \"term\": {  \n            \"log_level.keyword\": \"信息\"  \n          }  \n        },  \n        {  \n          \"term\": {  \n            \"product.keyword\": \"天融信堡垒机\"  \n          }  \n        }  \n      ],  \n      \"filter\": [  \n        {  \n          \"range\": {  \n            \"SparkTime\": {  \n              \"gte\": \"now-24h\",  \n              \"lt\": \"now\"  \n            }  \n          }  \n        }  \n      ]  \n    }  \n  },  \n  \"aggs\": {  \n    \"name\": {  \n      \"date_histogram\": {  \n        \"field\": \"SparkTime\",  \n        \"interval\": \"1h\",  \n        \"format\": \"HH:mm\",\n        \"time_zone\": \"+08:00\"\n      }  \n    }  \n  }  \n}',NULL,'