exists\": {\n            \"field\": \"action_type\"\n          }\n        },\n        {\n          \"bool\": {\n            \"must_not\": {\n              \"term\": {\n                \"action_type.keyword\": \"\"\n              }\n            }\n          }\n        }\n      ],\n      \"filter\": {\n        \"range\": {\n          \"SparkTime\": {\n            \"from\": \'${startTime<2023-10-01T00:00:00.000+0000>}\',\n            \"to\": \"now\"\n          }\n        }\n      }\n    }\n  }\n}',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'sec_all*',NULL,NULL,'super','管理员','2023-12-08 18:22:26','super','2023-12-11 15:53:52','100','1','100','','',1,NULL,0),('202312141849416960007','S-000697','测试创建报表','line','sql','','dajkdla',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','测试','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2023-12-14 18:49:42','super','2023-12-14 18:49:42','100','1','100','','',1,NULL,0),('202401181429212900000','S-000698','[集团安全运营中心]资产类型数据','line','sql','','SELECT\n           a.id AS assetTypeId,\n           a.type_name AS typeName,\n           a.ancestors,\n           (SELECT GROUP_CONCAT(id) FROM tb_sever_asset_type b WHERE FIND_IN_SET(a.id, b.ancestors)) AS childIds\n        FROM tb_sever_asset_type a\n        WHERE a.del_flag = 0',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}',NULL,'colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2024-01-18 14:29:21','super','2024-01-24 13:35:08','100','1','100','','',1,NULL,0),('202402211118149300005','S-000699','dly测试','line','sql','','啊啊大',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2024-02-21 11:18:15','super','2024-02-21 11:18:15','100','1','100','','',1,NULL,0),('202402271626003820046','S-000573','何景生-互联网资产系统数量','line','sql','','SELECT\n  IFNULL(tt.deptName, \'未归属组织\') AS deptName,\n  SUM(tt.num) AS total\nFROM\n  (SELECT\n    SUBSTRING_INDEX(dept_name, \'/\', 1) AS deptName,\n    \'1\' AS num\n  FROM\n    tb_asset_app_system\n  WHERE\n    del_flag = \'0\' AND is_publish_internet = \'0\') tt\nWHERE tt.deptName IS NOT NULL\n  AND tt.deptName != \'\'\nGROUP BY tt.deptName \nORDER BY total DESC',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"互联网资产系统数量\"}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2024-02-27 16:26:00','super','2024-03-13 14:14:42','100','1','100','','',1,NULL,0),('202402271632425060056','S-000574','何景生-年内等级保护测评占比','annular','static','','[\n	{\n		\"name\": \"一级\",\n		\"count\": 30\n	},\n	{\n		\"name\": \"二级\",\n		\"count\": 40\n	},\n	{\n		\"name\": \"三级\",\n		\"count\": 5\n	},\n	{\n		\"name\": \"四级\",\n		\"count\": 0\n	},\n	{\n		\"name\": \"五级\",\n		\"count\": 0\n	},\n	{\n		\"name\": \"未定级\",\n		\"count\": 25\n	}\n]',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\n	\"center\": [\n		\"34%\",\n		\"50%\"\n	],\n	\"radius\": [\n		\"30%\",\n		\"40%\"\n	],\n	\"legendRight\": \"5%\",\n	\"legendData\": [\n		\"五级\",\n		\"四级\",\n		\"三级\",\n		\"二级\",\n		\"一级\",\n		\"未定级\"\n	],\n	\"legendDataColor\": {\n		\"五级\": \"#D06773\",\n		\"四级\": \"#FFA39E\",\n		\"三级\": \"#FFC5B8\",\n		\"二级\": \"#FFCA8F\",\n		\"一级\": \"#C5C0FF\",\n		\"未定级\": \"#CAD0DF\"\n	},\n	\"showNum\": true\n}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2024-02-27 16:32:43','super','2024-02-27 16:39:11','100','1','100','','',1,NULL,0),('202402271633029620057','S-000573','何景生-待测试系统数量','count','static','','[{\"COUNT\":25}]',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"待测试系统数量\"}','colorgroup16','','1','1','4','3',NULL,0,'',NULL,NULL,'super','管理员','2024-02-27 16:33:03','super','2024-02-27 16:33