auto_report WHERE DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) AS COUNT',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"问题总数/个\"}','blue',NULL,'','','','','/profile/upload/2021/11/24/202111241001238750000.png',0,'',NULL,NULL,'super','管理员','2021-11-17 19:47:37','super','2022-01-20 20:51:57','100','0','100',NULL,NULL,NULL,NULL,NULL),('269','S-000074','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-已完成整改问题数量','count','sql','',' SELECT (\nSELECT COUNT(1) AS COUNT FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (9) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) + (\nSELECT COUNT(1) AS COUNT  FROM tb_risk_auto_report WHERE order_status=\'已关闭\' AND DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) AS COUNT',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"已完成整改问题数量/个\"}','blue',NULL,'','','','','/profile/upload/2021/11/24/202111241009184920001.png',0,'',NULL,NULL,'super','管理员','2021-11-17 19:48:53','super','2022-01-20 20:52:40','100','0','100',NULL,NULL,NULL,NULL,NULL),('270','S-000075','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-未完成整改问题数量','count','sql','',' SELECT (\nSELECT COUNT(1) AS COUNT FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (2,3,4,5,6,7,8) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) + (\nSELECT COUNT(1) AS COUNT  FROM tb_risk_auto_report WHERE order_status!=\'已关闭\' AND DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) AS COUNT',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"未完成整改问题数量/个\"}','blue',NULL,'','','','','/profile/upload/2021/11/24/202111241009563200002.png',0,'',NULL,NULL,'super','管理员','2021-11-17 19:49:32','super','2022-01-20 20:53:13','100','0','100',NULL,NULL,NULL,NULL,NULL),('271','S-000076','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-整改完成率','count','sql','','select CONCAT(CONVERT(num/total*100,DECIMAL(10,2)), \'%\') as count from ( SELECT ((\nSELECT COUNT(1) AS COUNT FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (9) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) + (\nSELECT COUNT(1) AS COUNT  FROM tb_risk_auto_report WHERE order_status=\'已关闭\' AND DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) ) AS num , ( (\nSELECT COUNT(1) AS COUNT FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (2,3,4,5,6,7,8,9) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) + (\nSELECT COUNT(1) AS COUNT  FROM tb_risk_auto_report WHERE DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\"\n) ) as total ) a',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"title\":\"整改完成率\"}','blue',NULL,'','','','','/profile/upload/2021/11/24/202111241010229810003.png',0,'',NULL,NULL,'super','管理员','2021-11-17 19:51:06','super','2022-01-20 20:56:44','100','0','100',NULL,NULL,NULL,NULL,NULL),('272','S-000077','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-风险级别分布','pie','sql','','SELECT SUM(COUNT) as count,NAME FROM\n((SELECT COUNT(1) AS COUNT, CASE risk_level  WHEN 1 THEN \'高风险\' WHEN 2 THEN \'中风险\' ELSE \'低风险\' END AS NAME FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (2,3,4,5,6,7,8,9) AND DATE_FORMAT(a.create_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" GROUP BY risk_level )\nUNION\n(SELECT COUNT(1) AS COUNT, risk_level_label AS NAME  FROM tb_risk_auto_report where  DATE_FORMAT(create_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" GROUP BY risk_level_label)\n) a GROUP BY NAME',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'50%\', \'45%\'],\"radius\":[\"40%\", \"60%\"],\"orient\":\"horizontal\",\"legendIcon\":\"circle\",\"orientDir\":\"bottom\",\"legendBottom\":\"5%\",\"legendLeft\":\"5%\",\"legendRight\":\"5%\",legendData:[\"高风险\",\"中风险\",\"低风险\"],\"legendDataColor\":{\"高风险\":\"#FFA39E\",\"中风险\":\"#FFCA8F\",\"低风险\":\"#91C3FF\"},\"showNum\":true}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-11-17 19:55:02','管理员(super)','2022-06-15 17:41:41','100','1','100',NULL,NULL,NULL,NULL,NULL),('273','S-000078','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-风险来源分布','pie','sql','','SELECT SUM(COUNT) as count ,NAME FROM\n((SELECT COUNT, d.dict_label AS NAME FROM (SELECT COUNT(1) AS COUNT, source_of_risk FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (2,3,4,5,6,7,8,9) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" GROUP BY source_of_risk) t LEFT JOIN (SELECT * FROM sys_dict_data WHERE dict_type= \'source_of_risk\' ) d ON d.dict_value = t.source_of_risk )\nUNION\n(SELECT COUNT(1) AS COUNT, source_label AS NAME  FROM tb_risk_auto_report where DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" GROUP BY source_label )\n) a GROUP BY NAME',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'50%\', \'45%\'],\"radius\":[\"40%\", \"60%\"],\"orient\":\"horizontal\",\"legendIcon\":\"circle\",\"orientDir\":\"bottom\",\"legendBottom\":\"5%\",\"legendLeft\":\"5%\",\"legendRight\":\"5%\",\"showNum\":true}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-11-17 19:55:44','super','2022-01-20 21:08:57','100','0','100',NULL,NULL,NULL,NULL,NULL),('274','S-000079','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-各单位整改进度','bar','sql','','SELECT t.*,d.dept_name AS NAME  FROM (\nSELECT SUM(COUNT) AS COUNT,dept, \'已完成\'  AS child FROM (\n(SELECT COUNT(1) AS COUNT, first_level_unit AS dept FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (9) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" and first_level_unit !=\'\' GROUP BY first_level_unit\n) UNION (\nSELECT COUNT(1) AS COUNT, first_level_dept_id AS dept  FROM tb_risk_auto_report WHERE order_status=\'已关闭\' AND DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" and first_level_dept_id != \'\' GROUP BY first_level_dept_id\n) ) a GROUP BY dept\nUNION (\nSELECT SUM(COUNT) AS COUNT, dept, \'未完成\'  AS child FROM (\n(SELECT COUNT(1) AS COUNT, first_level_unit AS dept FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (2,3,4,5,6,7,8) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" and first_level_unit !=\'\' GROUP BY first_level_unit\n) UNION (\nSELECT COUNT(1) AS COUNT, first_level_dept_id AS dept  FROM tb_risk_auto_report WHERE order_status!=\'已关闭\' AND DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" and first_level_dept_id != \'\' GROUP BY first_level_dept_id\n) ) a GROUP BY dept\n)) t LEFT JOIN sys_dept d ON t.dept = d.dept_id',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{legendData:[\"已完成\",\"未完成\"],\"legendDataColor\":{\"已完成\":\"#71a3f3\",\"未完成\":\"#ffc836\"} }','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-11-17 19:57:47','super','2022-01-21 10:42:29','100','0','100',NULL,NULL,NULL,NULL,NULL),('275','S-000080','[智慧安全作战指挥云平台｜风险态势｜风险态势] 全集团-风险类型分布','pie','sql','','SELECT SUM(COUNT) as count ,NAME FROM\n((SELECT COUNT, d.dict_label AS NAME FROM (SELECT COUNT(1) AS COUNT, problem_big_category FROM tb_custom_risk_assessment_approval a LEFT JOIN tb_process_risk_handle_business b ON a.id = b.form_id AND b.form_type = \'formRiskOrigin\' WHERE b.work_order_state IN (2,3,4,5,6,7,8,9) AND DATE_FORMAT(a.rectification_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" GROUP BY source_of_risk) t LEFT JOIN (SELECT * FROM sys_dict_data WHERE dict_type= \'risk_big_category\' ) d ON d.dict_value = t.problem_big_category )\nUNION\n(SELECT COUNT(1) AS COUNT, big_category AS NAME  FROM tb_risk_auto_report where DATE_FORMAT(rectification_start_time, \'%Y-%m-%d\') BETWEEN \"${startTime<2021-11-15>}\" AND \"${endTime<2021-11-16>}\" GROUP BY big_category )\n) a GROUP BY NAME',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"center\":[\'50%\', \'45%\'],\"radius\":[\"40%\", \"60%\"],\"orient\":\"horizontal\",\"legendIcon\":\"circle\",\"orientDir\":\"bottom\",\"legendBottom\":\"5%\",\"legendLeft\":\"5%\",\"legendRight\":\"5%\",\"showNum\":true}','colorgroup2