)  vulRingText, newCriticalVulNum, newHighriskVulNum, newMediumriskVulNum, newLowriskVulNum,newRepairWaitVulNum,newRepairDoneVulNum\n    FROM \n        (SELECT ( SELECT COUNT(1) FROM tb_risk_auto_original  WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') )  newVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original  WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND first_find_time &gt;= DATE_FORMAT(\'${prevStartTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${prevEndTime&lt;2022-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') )  preVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND vul_level = \'3\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newCriticalVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND vul_level = \'2\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newHighriskVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND vul_level = \'1\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newMediumriskVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND vul_level = \'0\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newLowriskVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND STATUS  = \'0\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newRepairWaitVulNum,\n		( SELECT COUNT(1) FROM tb_risk_auto_original WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND STATUS  = \'1\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\n		AND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2021-11-28 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newRepairDoneVulNum\n    ) t',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"newVulNum\",\"field\":\"newVulNum\"},{\"name\":\"preVulNum\",\"field\":\"preVulNum\"},{\"name\":\"vulRingText\",\"field\":\"vulRingText\"},{\"name\":\"newCriticalVulNum\",\"field\":\"newCriticalVulNum\"},{\"name\":\"newHighriskVulNum\",\"field\":\"newHighriskVulNum\"},{\"name\":\"newMediumriskVulNum\",\"field\":\"newMediumriskVulNum\"},{\"name\":\"newLowriskVulNum\",\"field\":\"newLowriskVulNum\"},{\"name\":\"newRepairWaitVulNum\",\"field\":\"newRepairWaitVulNum\"},{\"name\":\"newRepairDoneVulNum\",\"field\":\"newRepairDoneVulNum\"}]}','blue','','','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 14:06:51','super','2024-03-28 17:04:07','100','1','100',NULL,'',0,NULL,0),('412','S-000212','[智慧安全协同平台｜网络安全报告] 告警监测情况','table','sql','','SELECT (\r\n	SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n  ) alarmServerAssetNum, (\r\n		\r\n	SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'已失陷\' AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'已失陷\'  AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n	\r\n  ) newFallAlarmNum, (\r\n		\r\n	SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'疑似失陷\' AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'疑似失陷\'  AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n	  \r\n  ) newSuspectedFallAlarmNum, (	\r\n	 \r\n	  SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'攻击成功\' AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'攻击成功\'  AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n	  \r\n  ) newAttackSucceededAlarmNum,  (\r\n	  SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'疑似成功\' AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'疑似成功\'  AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n  ) newSuspectedSuccessAlarmNum, (\r\n		\r\n	  SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'企图\' AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'企图\'  AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n  ) newAttemptAlarmNum, (\r\n		\r\n	  SELECT IFNULL(SUM(1), 0) COUNT FROM (SELECT ip,alarm_id FROM (\r\n	    (\r\n	    SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'失败\' AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n		)\r\n		UNION ALL  (\r\n			SELECT attack_ip ip, alarm_id FROM tb_alarm_report  WHERE  attack_ip IN ( SELECT internal_ip FROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) AND alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n				AND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND attack_result_label = \'失败\'  AND order_status != \'无需处置\' \r\n		)        \r\n        ) t GROUP BY ip,alarm_id\r\n      ) s \r\n  ) newFailAlarmNum\r\n  \r\n  ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"alarmServerAssetNum\",\"field\":\"alarmServerAssetNum\"},{\"name\":\"newFallAlarmNum\",\"field\":\"newFallAlarmNum\"},{\"name\":\"newSuspectedFallAlarmNum\",\"field\":\"newSuspectedFallAlarmNum\"},{\"name\":\"newAttackSucceededAlarmNum\",\"field\":\"newAttackSucceededAlarmNum\"},{\"name\":\"newSuspectedSuccessAlarmNum\",\"field\":\"newSuspectedSuccessAlarmNum\"},{\"name\":\"newAttemptAlarmNum\",\"field\":\"newAttemptAlarmNum\"},{\"name\":\"newFailAlarmNum\",\"field\":\"newFailAlarmNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 15:28:42','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('413','S-000213','[智慧安全协同平台｜网络安全报告] 漏洞发现-漏洞检测情况','table','sql','','SELECT ( SELECT COUNT(1) COUNT   FROM tb_risk_auto_original  WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\nAND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2022-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) vulServerAssetNum,\n( SELECT COUNT( DISTINCT(vul_name) ) FROM tb_risk_auto_original  WHERE dept_name = \'${deptName&lt;润联科技&gt;}\' AND first_find_time &gt;= DATE_FORMAT(\'${startTime&lt;2021-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\')\nAND first_find_time &lt;= DATE_FORMAT(\'${endTime&lt;2022-01-01 00:00:00&gt;}\',\'%Y-%m-%d %H:%i:%S\') ) newDifferentVulNum',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"vulServerAssetNum\",\"field\":\"vulServerAssetNum\"},{\"name\":\"newDifferentVulNum\",\"field\":\"newDifferentVulNum\"}]}','blue','','','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 15:29:21','super','2024-03-28 16:59:32','100','1','100',NULL,'',0,NULL,0),('414','S-000214','[智慧安全协同平台｜网络安全报告] 告警受害IPTop','table','sql','','SELECT @rownum:=@rownum+1 AS alarmVictAssetSer, t.* FROM (\r\nSELECT  COUNT victAssetAlarmNum, internal_ip alarmVictAssetIP, IFNULL( instance , \"\" ) alarmVictAssetInstance ,\r\nIFNULL( company_name , \"-\" ) alarmVictAssetFirstUnit, IFNULL( sub_company_name , \"-\" ) alarmVictAssetSecondUnit FROM (\r\n\r\n\r\nSELECT internal_ip, instance,company_name,sub_company_name FROM (\r\nSELECT internal_ip, instance,CASE  LOCATE(\'/\',dept_name) WHEN 0 THEN \'\' ELSE SUBSTRING_INDEX(dept_name,\'/\',-1) END sub_company_name ,\r\ncompany_name FROM (\r\nSELECT internal_ip, instance, SUBSTRING_INDEX(affiliation_dept_name,\'/\',2) dept_name, SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) AS company_name\r\nFROM tb_asset ) aa) bb  WHERE company_name = \'${deptName<科技公司>}\'\r\n) s\r\nLEFT JOIN \r\n(\r\nSELECT COUNT(1) COUNT, ip FROM (\r\n		SELECT victimizedIp ip, alarm_id FROM (\r\n		SELECT\r\n		    a.*,\r\n		    SUBSTRING_INDEX( SUBSTRING_INDEX( a.victimized_ip, \',\', b.help_topic_id + 1 ), \',\', - 1 ) AS victimizedIp \r\n		FROM\r\n		    (SELECT victimized_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND alarm_time <= DATE_FORMAT(\'${endTime<2023-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND order_status != \'无需处置\'  ) a\r\n		    JOIN mysql.help_topic b ON b.help_topic_id < (\r\n			LENGTH( a.victimized_ip ) - LENGTH(\r\n			REPLACE ( a.victimized_ip, \',\', \'\' )) + 1 \r\n		    )  ) t\r\n		    WHERE victimizedIp IN (  SELECT internal_ip\r\nFROM tb_asset WHERE SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) = \'${deptName<科技公司>}\' ) GROUP BY victimizedIp, alarm_id\r\n			) a GROUP BY ip\r\n) v\r\nON v.ip = s.internal_ip  WHERE COUNT > 0 ORDER BY COUNT DESC LIMIT 10\r\n) t, (SELECT @rownum:=0) r',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"序号\",\"field\":\"alarmVictAssetSer\"},{\"name\":\"受害IP\",\"field\":\"alarmVictAssetIP\"},{\"name\":\"实例名称\",\"field\":\"alarmVictAssetInstance\"},{\"name\":\"所属组织\",\"field\":\"alarmVictAssetFirstUnit\"},{\"name\":\"所属组织\",\"field\":\"alarmVictAssetSecondUnit\"},{\"name\":\"告警数量\",\"field\":\"victAssetAlarmNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 17:46:17','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('415','S-000215','[智慧安全协同平台｜网络安全报告] 告警攻击IPTop','table','sql','','SELECT @rownum:=@rownum+1 AS alarmAttackAssetSer , t.* FROM (\r\nSELECT COUNT alarmAttackAssetNum, internal_ip alarmAttackAssetIP, IFNULL( instance , \"\" ) alarmAttackAssetInstance ,\r\n  IFNULL( company_name , \"\" ) alarmAttackAssetFirstUnit, IFNULL( sub_company_name , \"\" ) alarmAttackAssetSecondUnit  FROM (\r\nSELECT internal_ip, instance,company_name,sub_company_name FROM (SELECT internal_ip, instance,CASE  LOCATE(\'/\',dept_name) WHEN 0 THEN \'\' ELSE SUBSTRING_INDEX(dept_name,\'/\',-1) END sub_company_name ,\r\ncompany_name FROM (\r\nSELECT internal_ip, instance, SUBSTRING_INDEX(affiliation_dept_name,\'/\',2) dept_name, SUBSTRING_INDEX(affiliation_dept_name,\'/\',1) AS company_name\r\nFROM tb_asset ) aa) bb WHERE company_name = \'${deptName<科技公司>}\'\r\n) s\r\nLEFT JOIN \r\n(\r\nSELECT COUNT(1) COUNT, attack_ip FROM (\r\n SELECT attack_ip, alarm_id FROM tb_alarm_report WHERE alarm_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\nAND alarm_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND order_status != \'无需处置\' GROUP BY attack_ip,alarm_id ) a\r\n) v \r\nON v.attack_ip = s.internal_ip  WHERE COUNT > 0 ORDER BY COUNT DESC LIMIT 10\r\n\r\n) t, (SELECT @rownum:=0) r ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"序号\",\"field\":\"alarmAttackAssetSer\"},{\"name\":\"攻击IP\",\"field\":\"alarmAttackAssetIP\"},{\"name\":\"实例名称\",\"field\":\"alarmAttackAssetInstance\"},{\"name\":\"所属组织\",\"field\":\"alarmAttackAssetFirstUnit\"},{\"name\":\"所属组织\",\"field\":\"alarmAttackAssetSecondUnit\"},{\"name\":\"告警数量\",\"field\":\"alarmAttackAssetNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 17:46:52','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('416','S-000216','[智慧安全协同平台｜网络安全报告] 漏洞发现-漏洞IPTop','table','sql','','SELECT @rownum:=@rownum+1 AS vulVictAssetSer , t.* FROM (\r\n\r\nSELECT a.*, IFNULL(u.newRepairWaitVulNum, 0) newRepairWaitVulNum, IFNULL(d.newRepairDnoeVulNum, 0) newRepairDnoeVulNum FROM \r\n(SELECT COUNT(1) newAssetVulSum, ip vulVictAssetIP, instance_name vulictAssetInstance,\r\nIFNULL(dept_name, \'-\') vulVictAssetFirstUnit,\r\nIFNULL(sub_company_name, \'-\') vulVictAssetSecondUnit FROM tb_risk_auto_original \r\nWHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n	AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') \r\n	GROUP BY ip ORDER BY newAssetVulSum DESC LIMIT 10) a\r\n	LEFT JOIN \r\n	\r\n		( SELECT COUNT(1) newRepairWaitVulNum , ip FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n		AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')  \r\n		AND ip IN  ( SELECT ip FROM ( SELECT COUNT(1) COUNT, ip FROM tb_risk_auto_original \r\n			WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') \r\n			GROUP BY ip ORDER BY COUNT DESC LIMIT 100 )  t )\r\n		AND STATUS = 0 GROUP BY ip\r\n		) u ON a.vulVictAssetIP = u.ip\r\n		\r\n	LEFT JOIN \r\n	\r\n		( SELECT COUNT(1) newRepairDnoeVulNum , ip FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n		AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')  \r\n		AND ip IN  ( SELECT ip FROM ( SELECT COUNT(1) COUNT, ip FROM tb_risk_auto_original \r\n			WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n			AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') \r\n			GROUP BY ip ORDER BY COUNT DESC LIMIT 100 )  t )\r\n		AND STATUS = 1 GROUP BY ip\r\n		) d ON a.vulVictAssetIP = d.ip\r\n    ORDER BY newAssetVulSum DESC\r\n	) t, (SELECT @rownum:=0) r ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"序号\",\"field\":\"vulVictAssetSer\"},{\"name\":\"IP\",\"field\":\"vulVictAssetIP\"},{\"name\":\"实例名称\",\"field\":\"vulictAssetInstance\"},{\"name\":\"所属组织\",\"field\":\"vulVictAssetFirstUnit\"},{\"name\":\"所属组织\",\"field\":\"vulVictAssetSecondUnit\"},{\"name\":\"新增漏洞数\",\"field\":\"newAssetVulSum\"},{\"name\":\"待修复漏洞数\",\"field\":\"newRepairWaitVulNum\"},{\"name\":\"已修复漏洞数\",\"field\":\"newRepairDnoeVulNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 17:48:32','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('417','S-000217','[智慧安全协同平台｜网络安全报告] 漏洞发现-漏洞名称Top','table','sql','','SELECT @rownum:=@rownum+1 AS newDifferentVulSer , t.* FROM ( SELECT a.newVulName, a.newVulNameSum, IFNULL(u.newVulRepairWaitNum, 0) newVulRepairWaitNum, IFNULL(d.newVulRepairDoneNum, 0) newVulRepairDoneNum FROM ( \r\n SELECT COUNT(1) newVulNameSum , vul_name AS newVulName FROM tb_risk_auto_original  WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\nAND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') GROUP BY vul_name ORDER BY newVulNameSum DESC LIMIT 10 \r\n) a\r\nLEFT JOIN \r\n(  SELECT COUNT(1) newVulRepairWaitNum ,  vul_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\nAND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND vul_name IN  ( SELECT NAME FROM ( SELECT COUNT(1) COUNT, vul_name AS NAME FROM tb_risk_auto_original  \r\n WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\nAND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') GROUP BY vul_name ORDER BY COUNT DESC LIMIT 100 ) t ) \r\n AND STATUS = 0 GROUP BY vul_name ) u\r\n ON a.newVulName  = u.vul_name\r\n LEFT JOIN \r\n(\r\n SELECT COUNT(1) newVulRepairDoneNum ,  vul_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\nAND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND vul_name IN  ( SELECT NAME FROM ( SELECT COUNT(1) COUNT, vul_name AS NAME FROM tb_risk_auto_original  \r\n WHERE dept_name = \'${deptName<科技公司>}\' AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\nAND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') GROUP BY vul_name ORDER BY COUNT DESC LIMIT 100 ) t ) \r\n AND STATUS = 1 GROUP BY vul_name\r\n) d\r\nON d.vul_name  = a.newVulName\r\nORDER BY newVulNameSum DESC\r\n) t, (SELECT @rownum:=0) r  ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"序号\",\"field\":\"newDifferentVulSer\"},{\"name\":\"漏洞名称\",\"field\":\"newVulName\"},{\"name\":\"新增数量\",\"field\":\"newVulNameSum\"},{\"name\":\"待修复数\",\"field\":\"newVulRepairWaitNum\"},{\"name\":\"已修复数\",\"field\":\"newVulRepairDoneNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 17:49:02','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('418','S-000218','[智慧安全协同平台｜网络安全报告] 漏洞发现-待修复漏洞组织','table','sql','','SELECT @rownum:=@rownum+1 AS newUnitRepairWaitSer , t.* FROM (\r\nselect * from (\r\n(\r\n	SELECT  IFNULL(COUNT, 0) newUnitRepairWaitNum, dept_name newUnitNameRepairWait FROM  ( SELECT dept_name FROM sys_dept WHERE parent_id = \'${deptId<205>}\') d\r\n	LEFT JOIN (\r\n	SELECT COUNT(1) COUNT , sub_company_name FROM (\r\n		SELECT ip, sub_company_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 0 AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n		AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') \r\n		) t GROUP BY sub_company_name\r\n	) s\r\n	ON d.dept_name = s.sub_company_name\r\n	ORDER BY newUnitRepairWaitNum DESC LIMIT 0,1000	\r\n)\r\nUNION\r\n( \r\n	SELECT IFNULL(COUNT, 0) newUnitRepairWaitNum, sub_company_name newUnitNameRepairWait FROM ( SELECT COUNT(1) COUNT , sub_company_name FROM (\r\n		SELECT ip,sub_company_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 0 AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n		AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') and sub_company_name IS NOT NULL \r\n	) t GROUP BY sub_company_name ) s WHERE s.sub_company_name NOT IN ( SELECT dept_name FROM sys_dept WHERE parent_id = \'${deptId<205>}\' ) \r\n	ORDER BY newUnitRepairWaitNum DESC LIMIT 0,1000	\r\n)\r\nUNION \r\n(\r\n	SELECT COUNT(1) newUnitRepairWaitNum, \'空\' newUnitNameRepairWait FROM ( SELECT ip, sub_company_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 0 AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n	AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND sub_company_name IS NULL ) r\r\n)\r\n) a\r\nWHERE  newUnitNameRepairWait != \'空\' OR ( newUnitNameRepairWait = \'空\' AND newUnitRepairWaitNum != 0  )\r\n) t , (SELECT @rownum:=0) r ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"序号\",\"field\":\"newUnitRepairWaitSer\"},{\"name\":\"单位名称\",\"field\":\"newUnitNameRepairWait\"},{\"name\":\"待修复漏洞数\",\"field\":\"newUnitRepairWaitNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 17:51:20','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('419','S-000219','[智慧安全协同平台｜网络安全报告] 漏洞发现-已修复漏洞组织','table','sql','','SELECT @rownum:=@rownum+1 AS newUnitRepairDoneSer , t.* FROM (\r\nselect * FROM (\r\n(\r\n	SELECT  IFNULL(COUNT, 0) newUnitRepairDoneNum, dept_name newUnitNameRepairDone FROM  ( SELECT dept_name FROM sys_dept WHERE parent_id = \'${deptId<205>}\') d\r\n	LEFT JOIN (\r\n	SELECT COUNT(1) COUNT , sub_company_name FROM (\r\n	SELECT ip,sub_company_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 1 AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n	AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') \r\n	) t GROUP BY sub_company_name\r\n	) s\r\n	ON d.dept_name = s.sub_company_name\r\n	ORDER BY newUnitRepairDoneNum DESC LIMIT 0,1000	\r\n)\r\nUNION\r\n( \r\n	SELECT IFNULL(COUNT, 0) newUnitRepairDoneNum, sub_company_name newUnitNameRepairDone FROM ( SELECT COUNT(1) COUNT , sub_company_name FROM (\r\n	SELECT ip,sub_company_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 1 AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n	AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND sub_company_name IS NOT NULL\r\n	) t GROUP BY sub_company_name ) s WHERE s.sub_company_name NOT IN ( SELECT dept_name FROM sys_dept WHERE parent_id = \'${deptId<205>}\' )\r\n	ORDER BY newUnitRepairDoneNum DESC LIMIT 0,1000	\r\n)\r\nUNION \r\n(\r\n	SELECT COUNT(1) newUnitRepairDoneNum, \'空\' newUnitNameRepairDone FROM ( SELECT ip, sub_company_name FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 1 AND first_find_time >= DATE_FORMAT(\'${startTime<2021-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\')\r\n	AND first_find_time <= DATE_FORMAT(\'${endTime<2022-01-01 00:00:00>}\',\'%Y-%m-%d %H:%i:%S\') AND sub_company_name IS NULL\r\n	)t\r\n)  ) a\r\nWHERE  newUnitNameRepairDone != \'空\' OR ( newUnitNameRepairDone = \'空\' AND newUnitRepairDoneNum != 0  )\r\n) t, (SELECT @rownum:=0) r ',NULL,'{\"timeType\":\"0\",\"dateStart\":\"\",\"dateEnd\":\"\",\"recentlyTime\":\"\"}','{\"tableHeader\":[{\"name\":\"序号\",\"field\":\"newUnitRepairDoneSer\"},{\"name\":\"单位名称\",\"field\":\"newUnitNameRepairDone\"},{\"name\":\"已修复漏洞数\",\"field\":\"newUnitRepairDoneNum\"}]}','blue',NULL,'','','','',NULL,0,'',NULL,NULL,'super','管理员','2021-12-09 17:51:46','super','2022-11-01 15:55:15','100','1','100',NULL,NULL,NULL,NULL,NULL),('420','S-000220','[智慧安全协同平台｜网络安全报告] 漏洞发现-待修复漏洞实例Top','table','sql','','SELECT @rownum:=@rownum+1 AS newInstanceRepairWaitSer , t.* FROM (\r\nSELECT COUNT(1) newInstanceRepairWaitNum, instance_name newInstanceNameRepairWait FROM tb_risk_auto_original WHERE dept_name = \'${deptName<科技公司>}\' AND STATUS = 0 AND first_find_time >= DATE_