CREATE TABLE `tb_visual_chart202300712` (
  `id` varchar(64) NOT NULL COMMENT '主键ID',
  `code` varchar(80) NOT NULL COMMENT '报表编号',
  `name` varchar(100) DEFAULT NULL COMMENT '标题',
  `type` varchar(64) DEFAULT NULL COMMENT '类型',
  `data_type` varchar(64) DEFAULT NULL COMMENT '数据类型（dsl、sql、static）',
  `source` varchar(512) DEFAULT NULL COMMENT '数据来源',
